-- Signals registry: ONE generic set, no vertical content (product owner
-- decision R22, 2026-11-14, docs/specs/topics/02-open-questions.md § F).
-- The registry was written for a pilot wrongly assumed to be a wine / spirits
-- distributor. This migration:
--   1. deletes 7 alcohol-only codes (EGAIS_ISSUE, EGAIS_ISSUE_RESOLVED,
--      MARKING_ISSUE, LICENSE_EXPIRING, EXCISE_PRICE_QUERY, TASTING_REQUESTED,
--      ALLOCATION_REQUESTED) with their relations, stage-rule templates,
--      overrides and stored instances (hard delete on purpose: R22);
--   2. renames blocks DS1–DS7 to O–U with neutral labels;
--   3. rewrites the texts of every code that carried wine / alcohol / HoReCa
--      examples or «IN4COM: …» notes (generated from the reviewed text set);
--   4. cleans risk types, stage-rule templates (generic deal types), relations
--      and the pack description;
--   5. records one new registry version (max + 1) with change rows.
-- Re-runnable: deletes / renames are guarded, text updates are idempotent,
-- the version is written only once (guard on change row 'r22:summary').

-- 1. Alcohol-only codes ──────────────────────────────────────────────────────
DELETE FROM "organization_signal_override" WHERE "code" IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED');
--> statement-breakpoint
DELETE FROM "signal_pack_override" WHERE "code" IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED');
--> statement-breakpoint
DELETE FROM "signal_stage_rule" WHERE "code" IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED');
--> statement-breakpoint
DELETE FROM "signal_relation" WHERE "code_a" IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED')
  OR "code_b" IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED');
--> statement-breakpoint
DELETE FROM "signal_instance" WHERE "code" IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED');
--> statement-breakpoint
UPDATE "signal_category" SET "closes_codes" = ARRAY(
  SELECT x FROM unnest("closes_codes") x
  WHERE x NOT IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED'))
WHERE "closes_codes" && ARRAY['EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED']::text[];
--> statement-breakpoint
UPDATE "signal_category" SET "successor_code" = NULL
WHERE "successor_code" IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED');
--> statement-breakpoint
UPDATE "deal_risk_type" SET
  "trigger_codes" = ARRAY(SELECT x FROM unnest("trigger_codes") x WHERE x NOT IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED')),
  "clear_codes" = ARRAY(SELECT x FROM unnest("clear_codes") x WHERE x NOT IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED'))
WHERE "trigger_codes" && ARRAY['EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED']::text[]
   OR "clear_codes" && ARRAY['EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED']::text[];
--> statement-breakpoint
DELETE FROM "signal_category" WHERE "code" IN ('EGAIS_ISSUE','EGAIS_ISSUE_RESOLVED','MARKING_ISSUE','LICENSE_EXPIRING','EXCISE_PRICE_QUERY','TASTING_REQUESTED','ALLOCATION_REQUESTED');
--> statement-breakpoint

-- 2. Blocks DS1–DS7 → O–U ────────────────────────────────────────────────────
INSERT INTO "signal_block" ("code", "pack_code", "label_ru", "sort", "audience", "first_party_only", "internal_only")
SELECT n."code", b."pack_code", n."label_ru", b."sort", b."audience", b."first_party_only", b."internal_only"
FROM (VALUES
  ('DS1', 'O', 'Заказы'),
  ('DS2', 'P', 'Наличие, образцы, промо'),
  ('DS3', 'Q', 'Ассортимент клиента и новые точки'),
  ('DS4', 'R', 'Доставка и возвраты'),
  ('DS5', 'S', 'Документы'),
  ('DS6', 'T', 'Оплата и взаиморасчёты'),
  ('DS7', 'U', 'Предложено дополнительно')
) AS n("old", "code", "label_ru")
JOIN "signal_block" b ON b."code" = n."old"
ON CONFLICT ("code") DO NOTHING;
--> statement-breakpoint
UPDATE "signal_category" SET "block_code" = CASE "block_code"
  WHEN 'DS1' THEN 'O' WHEN 'DS2' THEN 'P' WHEN 'DS3' THEN 'Q' WHEN 'DS4' THEN 'R'
  WHEN 'DS5' THEN 'S' WHEN 'DS6' THEN 'T' WHEN 'DS7' THEN 'U' END
WHERE "block_code" IN ('DS1','DS2','DS3','DS4','DS5','DS6','DS7');
--> statement-breakpoint
DELETE FROM "signal_block" WHERE "code" IN ('DS1','DS2','DS3','DS4','DS5','DS6','DS7');
--> statement-breakpoint

-- 3. Code texts (generated from the reviewed text set) ──────────────────────
UPDATE "signal_category" SET "definition_ru" = 'Клиент берёт у нас только одну группу товаров (например, только расходные материалы), хотя по профилю похожих клиентов ему подходят и другие группы (оборудование, сервисное обслуживание). Припарковано в v204: нет основания для рекомендации без отраслевого правила или сравнения клиентов.', "boundary_ru" = 'Клиент сам спросил о другой группе → SALES_NEW_DEMAND или SALES_PRICE_REQUEST. Клиент по профилю или формату не может брать группу (например, у него нет оборудования, к которому нужны эти товары) — не пробел.', "example_ru" = '«за 12 мес. клиент брал только расходные материалы (18 заказов); 72 % похожих клиентов берут ещё запчасти и сервисное обслуживание»', "card_note_ru" = 'Предложи сочетание с другой группой только с понятной пользой для клиента (задачи, сроки, сезон), а не потому, что это больше выручки для нас.', "updated_at" = now() WHERE "code" = 'ACCOUNT_CROSS_SELL_GAP';
--> statement-breakpoint
UPDATE "signal_category" SET "example_ru" = '«сегмент A; последняя встреча 12.07.2026 (презентация у клиента); прошло 122 дня; норма — раз в 30 дней»', "updated_at" = now() WHERE "code" = 'ACCOUNT_MEETING_OVERDUE';
--> statement-breakpoint
UPDATE "signal_category" SET "card_note_ru" = 'Предложи менеджеру коротко связаться с закупщиком или пользователем продукта у клиента (по роли): как прошла поставка, как работают позиции, и что нужно к следующему заказу.', "updated_at" = now() WHERE "code" = 'ACCOUNT_NEW_FOLLOWUP';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Первый заказ нового клиента вообще → ACCOUNT_NEW_FOLLOWUP. Клиент снова взял позицию после перерыва — не новая. Новая партия или модификация той же позиции, если в каталоге это та же позиция — не новая. Клиент в письме просит ввести позиции в ассортимент → LISTING_OPPORTUNITY.', "example_ru" = '«заказ № 1245 от 05.11.2026: впервые взяли 2 позиции — кабель ВВГнг 3×2,5 (500 м), автоматический выключатель 16 А (40 шт.)»', "counter_example_ru" = '«заказ № 1250: розетка двойная накладная, последний раз брали в марте 2026» → позиция не новая.', "card_note_ru" = 'Назови новую позицию и предложи менеджеру при следующем контакте узнать, как она подошла клиенту или его покупателям, и показать близкие позиции портфеля.', "updated_at" = now() WHERE "code" = 'ACCOUNT_PRODUCT_NEW';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Клиент вообще перестал заказывать → ACCOUNT_DORMANT. Позиция у нас выведена из каталога или её нет у поставщика → не этот код (INTERNAL_PRODUCT_STATUS_UPDATE или SUPPLIER_DELIVERY_DELAY). Клиент сам написал «убираем из ассортимента» → DELISTING_RISK. Общий объём упал, а позиция берётся → ACCOUNT_REVENUE_DECLINE_YOY.', "example_ru" = '«Картридж фильтра ФК-10: 9 заказов за 24 мес., ритм 28 дней; последний заказ позиции 12.06.2026 (147 дней назад); последний заказ клиента 28.10.2026»', "counter_example_ru" = '«Картридж фильтра ФК-10: последний заказ 12.06.2026; позиция снята с продажи (статус в каталоге — неактивна)» → причина у нас, не у клиента.', "card_note_ru" = 'Назови позицию, обычный ритм и дату последнего заказа; предложи менеджеру узнать у закупщика или технического специалиста клиента (по роли), почему позицию больше не берут, и только потом предложить её снова или замену, а не скидку.', "updated_at" = now() WHERE "code" = 'ACCOUNT_PRODUCT_STOPPED';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Клиент не заказывает дольше своего ритма → ACCOUNT_DORMANT (не этот код). Перестал брать отдельную позицию, а общий объём держится → ACCOUNT_PRODUCT_STOPPED. Клиент сам написал, что выводит наши позиции из ассортимента → DELISTING_RISK. Падение ниже порога или на малой базе — нет сигнала. Отмена конкретного заказа в письме → SALES_BOOKING_CANCELLED (он ведёт).', "card_note_ru" = 'Напиши, что клиент покупает у нас меньше, чем год назад (цифры и период), и предложи менеджеру связаться с закупщиком или руководителем клиента (по роли), чтобы узнать причину и планы, пока следующий период открыт; ценовое предложение только после этого.', "updated_at" = now() WHERE "code" = 'ACCOUNT_REVENUE_DECLINE_YOY';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Один крупный заказ в письме → это заказ (ORDER_REQUESTED), не тренд. Рост ниже порога или на малой базе — нет сигнала. Клиент сам сообщил об открытии новой точки → NEW_VENUE_OPENING.', "updated_at" = now() WHERE "code" = 'ACCOUNT_REVENUE_GROWTH_YOY';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Конкурент или продукт из его портфеля получает награду, рейтинг или премию (конкурс, отраслевой рейтинг поставщиков).', "boundary_ru" = 'Награда нашего клиента → SIGNAL_AWARD. Награда нашего партнёра или его продукта → PARTNER_AWARD.', "cues_prompt_ru" = ARRAY['золотая медаль', 'лучший поставщик года', 'победитель конкурса', 'высший балл', 'вошёл в рейтинг', 'премия', 'гран-при']::text[], "synonyms_ru" = '{"chat": ["Альянс взял золото", "их новый станок взял гран-при выставки", "им дали премию"], "terms": ["медаль", "балл", "рейтинг", "гран-при"], "business": ["удостоен награды", "признан лучшим поставщиком", "по итогам отраслевого конкурса"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_AWARD", "text": "«наш клиент попал в отраслевой рейтинг»"}, {"code": "PARTNER_AWARD", "text": "«продукт нашего партнёра получил золото»"}]'::jsonb, "example_ru" = '«ООО «ТехноАльянс» признано лучшим поставщиком года по версии отраслевой премии.»', "counter_example_ru" = '«Наш клиент ООО «Лаванда» вошёл в отраслевой рейтинг» → SIGNAL_AWARD.', "updated_at" = now() WHERE "code" = 'COMPETITOR_AWARD';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Конкурент расширяется в наших регионах: новый склад, филиал, новый регион доставки, новая команда продаж для нашего сегмента клиентов.', "synonyms_ru" = '{"chat": ["Альянс зашёл в Питер", "у них теперь склад в Казани", "набирают торговых под наш сегмент"], "terms": ["РЦ", "филиал", "география", "торговые представители"], "business": ["объявил об открытии регионального представительства", "ввод в эксплуатацию склада", "расширение географии поставок"]}'::jsonb, "anti_cues_ru" = '[{"code": "NEW_VENUE_OPENING", "text": "«наш клиент открывает второй филиал»"}, {"code": "COMPETITOR_FUNDING", "text": "«Альянс получил инвестиции»"}]'::jsonb, "example_ru" = '«ООО «ТехноАльянс» открыло распределительный центр в Екатеринбурге и запускает доставку по Уралу.»', "counter_example_ru" = '«ООО «ТехноАльянс» открыло офис в Ереване» → вне наших регионов, нет сигнала.', "updated_at" = now() WHERE "code" = 'COMPETITOR_EXPANSION';
--> statement-breakpoint
UPDATE "signal_category" SET "cues_prompt_ru" = ARRAY['привлёк инвестиции', 'новый акционер', 'вошёл в капитал', 'купил долю', 'приобрёл компанию', 'кредитная линия на развитие', 'сделка по покупке поставщика']::text[], "example_ru" = '«Инвестфонд «Восток Капитал» приобрёл 40 % ООО «ТехноАльянс» для развития сети складов.»', "counter_example_ru" = '«ТехноАльянс открыл склад в Казани» → COMPETITOR_EXPANSION.', "updated_at" = now() WHERE "code" = 'COMPETITOR_FUNDING';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Наш конкурент (другой поставщик тех же товаров или услуг) потерял клиента или расстался с ним: сеть вывела его позиции, завод сменил поставщика, контракт не продлён, тендер объявлен заново. Это повод проверить, есть ли смысл в первом контакте с этим клиентом.', "boundary_ru" = 'Клиент ушёл от НАС → коды риска у нашего клиента (CONTRACT_TERMINATED, DELISTING_RISK). Клиент, не наш клиент, меняет поставщика, но бывший поставщик не наш конкурент → SIGNAL_AGENCY_CHANGE в агентском смысле не применяется; в остальных случаях нет сигнала. Конкурент сам закрывается или банкротится → SIGNAL_INSOLVENCY (если он в списке клиентов) или COMPETITOR_NEGATIVE_PRESS. Клиент лишь «присматривается к другим поставщикам» без решения → нет сигнала.', "synonyms_ru" = '{"chat": ["Ромашка ушла от Альянса", "Альянса выкинули из сети", "они больше не берут у Альянса", "завод ищет нового поставщика, Альянс всё", "у Альянса забрали холдинг"], "terms": ["делистинг", "вывод из матрицы", "повторный тендер", "перезапуск закупки"], "business": ["прекращено сотрудничество с", "договор поставки не пролонгирован", "объявлена повторная закупка", "сеть исключила из матрицы продукцию поставщика", "«рассматриваем альтернативных поставщиков» (только если сказано, что прежний ушёл)"], "patterns": ["клиент + «ушёл от / отказался от / расстался с» + конкурент", "конкурент + «потерял / лишился» + клиента"]}'::jsonb, "example_ru" = '«Сеть «Городской дом» с января прекращает сотрудничество с ООО «ТехноАльянс» и объявляет новый отбор поставщика электротоваров.»', "counter_example_ru" = '«Сеть «Городской дом» довольна ООО «ТехноАльянс» и продлила договор» → потери нет, нет сигнала.', "cues_prompt_ru" = ARRAY['сменил поставщика', 'отказался от поставок', 'расторг договор с', 'вывел из ассортимента позиции', 'не продлил контракт', 'тендер объявлен повторно', 'ищет нового поставщика', 'прекратил сотрудничество с']::text[], "updated_at" = now() WHERE "code" = 'COMPETITOR_LOST_CLIENT';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'О конкуренте выходит негативная информация: изъятие партии, проблемы с сертификацией или лицензией, судебный спор, проверка, массовые жалобы клиентов.', "cues_prompt_ru" = ARRAY['изъята партия', 'приостановлена лицензия', 'проверка контролирующего органа', 'контрафакт', 'иск к поставщику', 'срывает поставки', 'жалобы клиентов на']::text[], "synonyms_ru" = '{"chat": ["у Альянса забрали лицензию", "у них проблемы с сертификатами", "клиенты жалуются, что Альянс не возит"], "terms": ["отзыв сертификата", "предписание", "контрафакт", "арбитраж", "ФАС"], "business": ["приостановлено действие лицензии", "выявлена продукция без маркировки", "возбуждено дело", "арбитражный иск"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_NEGATIVE_PRESS", "text": "«у нашего клиента приостановлена лицензия»"}, {"code": "COMPETITOR_LOST_CLIENT", "text": "«Альянс ушёл из сети»"}]'::jsonb, "example_ru" = '«Контролирующий орган приостановил действие сертификатов ООО «ТехноАльянс» на основную линейку оборудования.»', "counter_example_ru" = '«У нашего клиента приостановили лицензию» → SIGNAL_NEGATIVE_PRESS.', "updated_at" = now() WHERE "code" = 'COMPETITOR_NEGATIVE_PRESS';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Наш конкурент (компания из списка конкурентов либо прямо названная в тексте конкурентом) получил нового клиента: вошёл в ассортимент сети, в список аккредитованных поставщиков завода, выиграл тендер или стал эксклюзивным поставщиком. Выигранный клиент обычно назван в том же тексте.', "boundary_ru" = 'Победитель не является нашим конкурентом → SIGNAL_ACCOUNT_WIN (или нет сигнала). Конкурент появился у НАШЕГО действующего клиента (клиент берёт у него часть позиций, сравнивает цены) → SIGNAL_COMPETITOR; клиент жалуется, что у конкурента дешевле → COMPLAINT_PRICE. Наша собственная победа → TEAM_DEAL_WON / SALES_BOOKING_RECEIVED. Конкурент лишь участвует в тендере, итог неизвестен → нет сигнала.', "cues_prompt_ru" = ARRAY['стал официальным поставщиком', 'выиграл тендер', 'вошёл в ассортимент сети', 'прошёл аккредитацию у', 'эксклюзивный поставщик', 'заключил договор поставки с', 'теперь поставляет в', 'новый клиент компании']::text[], "synonyms_ru" = '{"chat": ["ТехноАльянс зашёл в Магистраль", "они забрали сеть", "теперь у них весь завод", "холдинг ушёл к Альянсу", "слышал, Альянс выиграл тендер у строительной группы"], "terms": ["тендер", "44-ФЗ", "223-ФЗ", "листинг", "ввод в матрицу", "эксклюзив", "СТМ"], "business": ["по итогам тендера победителем признан", "заключён договор поставки", "определён поставщиком продукции", "получил право эксклюзивной дистрибуции", "стал партнёром сети по категории электротоваров"], "patterns": ["имя конкурента + «выиграл / получил / зашёл / стал поставщиком» + клиент"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_COMPETITOR", "text": "«наш клиент берёт часть позиций у Альянса»"}, {"code": "COMPLAINT_PRICE", "text": "«у Альянса на 10 % дешевле, пересмотрите цену» от клиента"}, {"code": "COMPETITOR_LOST_CLIENT", "text": "«Альянс потерял сеть»"}, {"code": null, "text": "«объявлен тендер, участвуют Альянс и мы»"}]'::jsonb, "example_ru" = '«По итогам закупки ООО «ТехноАльянс» признано поставщиком спецодежды для предприятий холдинга «Северная корона» на 2027 год.»', "counter_example_ru" = '«ООО «ТехноАльянс» подало заявку на участие в закупке холдинга «Северная корона»» → итога нет, нет сигнала.', "updated_at" = now() WHERE "code" = 'COMPETITOR_NEW_CLIENT';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'У конкурента меняется руководство или ключевые сотрудники: генеральный, коммерческий директор, бренд-менеджер, известный отраслевой эксперт.', "cues_prompt_ru" = ARRAY['назначен коммерческим директором', 'покинул компанию', 'новый генеральный директор', 'перешёл из', 'возглавил направление продаж', 'сменилось руководство']::text[], "synonyms_ru" = '{"chat": ["у Альянса новый коммерческий", "их бренд-менеджер ушёл", "Петров теперь у Альянса"], "terms": ["КД", "ГД", "бренд-менеджер", "директор по продажам"], "business": ["назначен на должность", "освобождён от должности", "кадровые перестановки в"]}'::jsonb, "anti_cues_ru" = '[{"code": "CONTACT_NEW_DECISION_MAKER", "text": "«у клиента новый закупщик»"}, {"code": "SIGNAL_C_LEVEL_CHANGE", "text": "«у клиента новый гендиректор»"}]'::jsonb, "example_ru" = '«Коммерческим директором ООО «ТехноАльянс» назначен бывший руководитель продаж крупной строительной группы.»', "counter_example_ru" = '«Новым генеральным директором нашего клиента ООО «Лаванда» назначен бывший управляющий сети» → SIGNAL_C_LEVEL_CHANGE.', "updated_at" = now() WHERE "code" = 'COMPETITOR_PERSONNEL';
