UPDATE "signal_category" SET "definition_ru" = 'То, что мы поставили или сделали, с дефектом: брак, ошибка, не тот товар или результат, техническая неисправность, рекламация. Например: заводской дефект, неисправность, повреждённая упаковка или маркировка.', "boundary_ru" = 'Пришло меньше — COMPLAINT_QUANTITY (ведёт). Бой, недовложение и пересорт при приёмке — DELIVERY_DISCREPANCY; просьба вернуть товар — RETURN_REQUESTED (вместе с этим кодом, если причина — брак). Ошибка в счёте — INVOICE_OVERDUE (спор). Вкусовое «нам не понравилось» без дефекта — нет сигнала или SALES_OFFER_DECLINED.', "cues_prompt_ru" = ARRAY['брак', 'ошибка', 'не то', 'претензия', 'рекламация', 'возврат', 'дефект', 'повреждена упаковка']::text[], "synonyms_ru" = '{"chat": ["оборудование не включается", "краска отслаивается", "покупатели вернули, внутри трещины", "корпус треснул", "упаковка рваная", "прислали не то", "опять косяк", "это брак, заберите"], "terms": ["брак", "рекламация", "претензия", "несоответствие", "«пересорт» (при приёмке → DELIVERY_DISCREPANCY)", "заводской дефект", "неисправность", "гарантийный случай", "некондиция"], "business": ["направляем претензию по качеству поставленного товара", "выявлены дефекты", "товар не соответствует заявленным характеристикам", "просим заменить бракованную продукцию", "прошу принять рекламацию", "в результате допущена ошибка в", "требуем возврата денежных средств за некачественный товар"], "patterns": ["«претензия / рекламация по» + товар или работа", "«не соответствует» + требованию", "«просим заменить / вернуть» + из-за дефекта"]}'::jsonb, "anti_cues_ru" = '[{"code": "COMPLAINT_QUANTITY", "text": "«пришло 30 вместо 50»"}, {"code": "DELIVERY_DISCREPANCY", "text": "«при приёмке 3 шт. бой»"}, {"code": "RETURN_REQUESTED", "text": "«хотим вернуть нераспроданное» без дефекта"}, {"code": null, "text": "«покупателям не зашёл цвет»"}]'::jsonb, "example_ru" = '«Из последней партии смесителей уже четыре штуки текут, покупатели вернули — просим заменить и разобраться с партией.»', "counter_example_ru" = '«Покупателям больше понравилась серая плитка, чем бежевая, в следующий раз возьмём её» → предпочтение, не дефект.', "note_ru" = 'Closed by: — (agency: `COMPLAINT_RESOLUTION_CONFIRMED`)
Relations: `COMPLAINT_QUANTITY` leads over this code (when too little was delivered); both with `COMPLAINT_ESCALATED`. Successor of retired `COMPLAINT_ERROR`.
Deal effect: per org rule, e.g. risk trigger **«Повторные жалобы»** (≥ 2 complaints of this client in 30 days).', "updated_at" = now() WHERE "code" = 'COMPLAINT_QUALITY';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Неверное качество, дефект товара — COMPLAINT_QUALITY. Расхождение, выявленное при приёмке конкретной поставки (недовложение, бой, пересорт, акт ТОРГ-2), — DELIVERY_DISCREPANCY; этот код остаётся для жалобы на объём в целом (систематическая недопоставка, урезанный объём заказа без согласования). Наша плановая частичная отгрузка, о которой клиент знает, — нет сигнала.', "synonyms_ru" = '{"chat": ["пришло меньше, чем заказывали", "опять не всё привезли", "где ещё две коробки?", "вы нам ползаказа привезли", "половины позиций нет"], "terms": ["недопоставка", "недогруз", "«недовложение» (при приёмке → DELIVERY_DISCREPANCY)", "частичная отгрузка", "отгрузка не в полном объёме"], "business": ["поставка выполнена не в полном объёме", "по заказу № отгружено 30 из 50 единиц", "отсутствуют позиции, указанные в спецификации", "объём выполненных работ не соответствует договору", "систематически поставляете меньше заказанного"], "patterns": ["заказывали столько-то, а пришло меньше", "«не хватает» + позиции / штук", "не в полном объёме"]}'::jsonb, "anti_cues_ru" = '[{"code": "DELIVERY_DISCREPANCY", "text": "«две упаковки пришли битые»"}, {"code": "COMPLAINT_QUALITY", "text": "«товар с браком»"}, {"code": "DELIVERY_DISCREPANCY", "text": "«по акту приёмки недовложение 3 шт.»"}, {"code": null, "text": "«остаток заказа довезите в четверг, как договаривались»"}]'::jsonb, "counter_example_ru" = '«При приёмке обнаружили недовложение 2 упаковок, составили акт ТОРГ-2» → это DELIVERY_DISCREPANCY.', "note_ru" = 'Closed by: — (`DELIVERY_DISCREPANCY_RESOLVED` when the case is a discrepancy)
Relations: leads over `COMPLAINT_QUALITY` (when too little was delivered); both with `COMPLAINT_ESCALATED`.
