UPDATE "signal_category" SET "boundary_ru" = 'Поставщик сообщает НАМ, что его поставка задерживается, — SUPPLIER_DELIVERY_DELAY. Клиент не может до нас дозвониться, нам не отвечают на письма вообще — COMPLAINT_COMM (здесь — задержка конкретного результата или обещания). Нейтральный вопрос «когда привезёте?» без упрёка — не жалоба (это DELIVERY_SCHEDULE_REQUEST). Задержка по вине клиента — нет этого кода.', "synonyms_ru" = '{"chat": ["ну что там по доставке??", "где машина?", "опять не привезли", "вы обещали к обеду, уже вечер", "третий раз переносите", "бригада ждёт, а материала нет"], "terms": ["просрочка поставки", "срыв сроков", "неустойка за просрочку", "пени", "SLA"], "business": ["поставка по заказу № не выполнена в согласованный срок", "вы нарушили сроки, установленные договором", "до настоящего времени товар не получен", "обещанный отчёт так и не поступил", "просим объяснить причины задержки", "из-за задержки мы сорвали открытие"], "patterns": ["«до сих пор / так и не» + «не получили / не пришло»", "«опять / снова / в который раз» + «задержка / перенос»", "«обещали к» + дата"]}'::jsonb, "note_ru" = 'Closed by: — (agency: `COMPLAINT_RESOLUTION_CONFIRMED`)
Relations: both with `COMPLAINT_ESCALATED`.
Deal effect: per org rule, e.g. risk trigger **«Повторные жалобы»** (≥ 2 complaints of this client in 30 days).', "updated_at" = now() WHERE "code" = 'COMPLAINT_TIMING';
--> statement-breakpoint
UPDATE "signal_category" SET "cues_prompt_ru" = ARRAY['я больше не работаю в компании', 'последний рабочий день', 'покидаю компанию', 'ухожу из компании', 'по всем вопросам теперь обращайтесь к', 'перехожу в другую компанию', 'больше не сотрудник', 'передаю дела коллеге']::text[], "synonyms_ru" = '{"chat": ["я ухожу, всем спасибо", "я больше тут не работаю", "теперь пишите Свете, я ушла", "«у нас новый закупщик, старый ушёл»", "«вместо меня теперь будет Олег»"], "terms": ["увольнение", "последний день", "передача дел", "преемник"], "business": ["сообщаю, что с 15.11 я завершаю работу в компании", "это мой последний рабочий день", "благодарю за сотрудничество, дальше ваш вопрос ведёт", "Иванова И. И. больше не является сотрудником компании", "уволилась, письма не читаются"], "patterns": ["больше не работаю / не является сотрудником", "«последний рабочий день» + дата", "«по всем вопросам обращайтесь к» + новый человек (вместе с уходом)"]}'::jsonb, "example_ru" = '«Коллеги, 22 ноября мой последний рабочий день в компании, дела по закупкам оборудования передаю Ольге Смирновой.»', "note_ru" = 'Date gate: — (the last working day goes to `facts.deadlines`, owner = them)
Relevance window: until the last working day, then default
Relations: — in v204. Agency: the old company side is judged with `ACCOUNT_SPONSOR_SUPPORT_LOST`; the move itself is `PROSPECT_CONTACT_MOVED` (Q24-2).
Deal effect: per org rule. Typical: risk trigger on a change of the buyer / key contact — only when the person is linked to the deal (`deal_contact`) and no new contact is confirmed. Agency: «Потеря ключевого контакта» (Q24-2).', "updated_at" = now() WHERE "code" = 'CONTACT_LEAVING';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'В общении впервые появляется человек со стороны клиента, который принимает решения или утверждает закупку: новый директор, руководитель закупок, управляющий, главный инженер, категорийный менеджер сети.', "cues_prompt_ru" = ARRAY['я новый директор по закупкам', 'новый закупщик', 'новый категорийный менеджер', 'теперь решения по ассортименту принимаю я', 'вступил в должность', 'назначена руководителем', 'будет утверждать закупки', 'новый управляющий']::text[], "synonyms_ru" = '{"chat": ["«привет, я новый категорийный менеджер»", "«теперь ассортимент согласовываю я»", "я тут новый управляющий, давайте знакомиться", "закупки теперь на мне"], "terms": ["ЛПР", "ГД", "КД", "ФД", "закупщик", "байер", "категорийный менеджер", "главный инженер", "руководитель направления"], "business": ["представляюсь: с 01.11 я назначен коммерческим директором", "теперь вопросы закупки комплектующих курирую я", "прошу направлять предложения на моё имя", "новый руководитель отдела закупок — Петров П. П.", "согласование договоров теперь у финансового директора"], "patterns": ["«я новый / назначен(а)» + руководящая роль", "«теперь решения / согласование» + «за мной / у меня»"]}'::jsonb, "example_ru" = '«Добрый день! Я новый директор по закупкам сети, с декабря все вопросы по ассортименту стройматериалов согласовываются через меня.»', "note_ru" = 'Relations: — in v204. Agency: risk «Смена руководства клиента» (Maslov risk 5).
Deal effect: per org rule. Typical: risk trigger on a change of the buyer / decision maker (person linked to the deal; clears when the new person confirms the current terms); otherwise in-stage context (people).', "updated_at" = now() WHERE "code" = 'CONTACT_NEW_DECISION_MAKER';
