UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["добавила в чат Катю, она теперь заказы делает", "«я новенькая, буду оформлять заказы»", "пишите теперь мне по накладным"], "terms": ["контактное лицо", "ответственный", "новый сотрудник", "в копии"], "business": ["прошу направлять заявки на адрес нового сотрудника", "представляю нового менеджера по работе с поставщиками", "с сегодняшнего дня ваш контакт по логистике — Сидорова А. В.", "добавляю в копию нашего бухгалтера"], "patterns": ["«теперь по» + вопрос + «пишите / обращайтесь к» + человек", "«знакомьтесь / представляю» + новый сотрудник"]}'::jsonb, "updated_at" = now() WHERE "code" = 'CONTACT_NEW_KNOWN_ORG';
