UPDATE "signal_category" SET "example_ru" = '«Я в отпуске до 24 ноября, по срочным вопросам закупок обращайтесь к Ольге Смирновой, o.smirnova@tehnosfera.ru.»', "updated_at" = now() WHERE "code" = 'CONTACT_OOO';
