UPDATE "signal_category" SET "boundary_ru" = 'Соглашение о конфиденциальности — CONTRACT_NDA; о ПДн — CONTRACT_DPA. Документы на товар (сертификат, декларация соответствия ЕАЭС, паспорт или удостоверение качества) — DOCUMENTS_REQUESTED, не этот код. Пакет документов в составе тендерной заявки — часть SALES_TENDER_INVITATION, если отдельного запроса нет.', "counter_example_ru" = '«Пришлите, пожалуйста, декларации соответствия на партию из последней поставки» → документы на товар (DOCUMENTS_REQUESTED).', "updated_at" = now() WHERE "code" = 'CONTRACT_COMPLIANCE_DECLARATION';
