UPDATE "signal_category" SET "note_ru" = 'Emitted by: both (parser with date gate; process from the contract end date)
Closed by: — (the risk «Договор заканчивается без продления» clears with `CONTRACT_RENEWAL_INTENT` or a signed renewal)
Date gate: { fact: `contractEndDate`, test: within 0 to N days after the item, setting: `cards.frameExpiryWindowDays`, window: 56 }
Relevance window: until `contractEndDate`
Relations: `CONTRACT_RENEWAL_INTENT` leads over this code (the opportunity beats the warning).
Deal effect: per org rule. Usual: risk trigger «Договор заканчивается без продления» (no `CONTRACT_RENEWAL_INTENT` in the date window).
v2: kind event / emitted_by parser (read from text, kept by the date gate). The process watchdog on the contract end date comes in phase 8 with its own trigger_rule.', "updated_at" = now() WHERE "code" = 'CONTRACT_FRAME_EXPIRY';
--> statement-breakpoint
UPDATE "signal_category" SET "note_ru" = 'Closes: — (clears the risk «Договор заканчивается без продления»)
Relevance window: until the current contract end date, if known; else default
Relations: leads over `CONTRACT_FRAME_EXPIRY` (the opportunity beats the warning).
Deal effect: per org rule. Possible: deal entry (renewal). Agency (Q24-10): stage 4 only when the contract / service is identifiable, the next period or scope is defined and the client explicitly confirms the choice; otherwise context.', "updated_at" = now() WHERE "code" = 'CONTRACT_RENEWAL_INTENT';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Договор просто истёк, а продления нет — CONTRACT_NOT_RENEWED (watchdog). Отказ продлевать на следующий период до окончания срока — в агентском пакете CONTRACT_RENEWAL_DECLINED, в базе — этот код, только если клиент прямо прекращает отношения. Отмена одного заказа — SALES_BOOKING_CANCELLED (регулярного товарного заказа — ORDER_CANCELLED). Пауза в работе без расторжения — не этот код. Расторжение по нашей инициативе — не сигнал клиента. Угроза «будем вынуждены расторгнуть» без решения — COMPLAINT_* с эмоцией, не расторжение.', "note_ru" = 'Date gate: — (termination date goes to `facts.deadlines`)
Relations: leads over `CONTRACT_NOT_RENEWED` (an act beats the passing of time).
Deal effect: per org rule. Usual: outcome `lost` (or `cancelled`) for an open deal on this contract; otherwise context on the client. Never rewrites a won sale (Maslov §3.3).', "updated_at" = now() WHERE "code" = 'CONTRACT_TERMINATED';
--> statement-breakpoint
UPDATE "signal_category" SET "cues_prompt_ru" = ARRAY['решим после праздников', 'вернёмся к вопросу позже', 'пока не готовы', 'отложим до весны', 'комитет перенесли', 'вопрос с ассортиментом пока на паузе', 'руководство ещё не решило', 'давайте в следующем квартале']::text[], "synonyms_ru" = '{"chat": ["давайте после нового года", "пока на паузе", "директор ещё думает", "не до этого сейчас", "вернёмся позже", "комитет опять перенесли", "пока не решили"], "terms": ["перенос комитета", "пауза", "на согласовании у руководства", "после утверждения бюджета"], "business": ["решение по поставщику перенесено на после праздников", "обновление ассортимента откладываем до весны", "закупочный комитет перенесён, дату сообщим дополнительно", "к вопросу вернёмся в следующем квартале", "пока не готовы принять решение", "рассмотрение договора приостановлено до утверждения бюджета", "открытие сдвигается, вопрос поставок пока не актуален"], "patterns": ["решим / вернёмся / рассмотрим + позже / после + событие", "пока не + готовы / решили", "отложим / перенесли + решение / комитет / ввод"]}'::jsonb, "example_ru" = '«Обновление ассортимента пока откладываем, вернёмся к вопросу после праздников.»', "note_ru" = 'Статус: proposed (new) · target block after approval: Q
Closed by: — (the risk clears when a date and a next step are agreed; spec §9.4)
Relations: attaches to the deal topic (listing, new location, tender, contract); repeated mentions of the same postponement are one instance (spec §5.4 5a)
Deal effect: in-stage context; risk trigger «Решение откладывается» (`DECISION_DELAYED`, min_occurrences 2)', "updated_at" = now() WHERE "code" = 'DECISION_POSTPONED';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Клиент сообщает, что убирает наши позиции из ассортимента, каталога или матрицы, или больше не будет их закупать.', "boundary_ru" = 'Одна позиция закончилась у клиента и он её пока не дозаказывает → нет сигнала. Отмена одного заказа → ORDER_CANCELLED. Отказ от нового предложения, которого ещё не было в ассортименте → SALES_OFFER_DECLINED. Расторжение договора целиком → CONTRACT_TERMINATED. Сезонная ротация, о которой клиент говорит как о временной («летом уберём обогреватели») → нет сигнала.', "cues_prompt_ru" = ARRAY['выводим из каталога', 'убираем из ассортимента', 'больше не будем брать', 'выводим из матрицы', 'заменяем на другого поставщика', 'делистинг', 'не продлеваем позиции', 'уходим с вашей продукции']::text[], "synonyms_ru" = '{"chat": ["больше не берём", "вашу линейку убираем из каталога", "руководство решило сменить поставщика", "уходим на другой бренд", "эту позицию снимаем", "не продаётся, выводим", "доедаем остатки и всё"], "terms": ["делистинг", "вывод из матрицы", "ротация", "исключение из АМ", "распродажа остатков", "замена поставщика"], "business": ["по итогам ротации позиции выводятся из ассортимента", "принято решение исключить позиции из матрицы", "в новом каталоге ваших позиций не будет", "переходим на другого поставщика по категории крепежа", "позиции не прошли пересмотр матрицы", "с 1 января прекращаем закупку следующих позиций", "распродаём остатки и выводим"], "patterns": ["выводим / убираем / исключаем / снимаем + позиции / продукцию / бренд", "больше не + будем брать / закупать"]}'::jsonb, "anti_cues_ru" = '[{"code": null, "text": "«краска кончилась, пока не надо»"}, {"code": "ORDER_CANCELLED", "text": "«отменяем заказ на пятницу»"}, {"code": "CONTRACT_TERMINATED", "text": "«расторгаем договор поставки»"}, {"code": "SALES_OFFER_DECLINED", "text": "«ваше предложение не подходит»"}]'::jsonb, "example_ru" = '«По итогам пересмотра матрицы с января выводим ваши две модели фильтров, в категории остаётся один поставщик.»', "counter_example_ru" = '«Фильтры закончились, следующий заказ сделаем в январе» → позиция остаётся; это пауза, а не вывод.', "updated_at" = now() WHERE "code" = 'DELISTING_RISK';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'При приёмке поставки клиент находит расхождение с накладной: бой, недовложение (не хватает штук или упаковок), пересорт (не та серия, не та позиция), излишек, повреждённую упаковку, и просит его закрыть (довезти, заменить, скорректировать документы).', "boundary_ru" = 'Претензия к качеству товара (дефект, неисправность, несоответствие характеристикам) → base COMPLAINT_QUALITY. Опоздание доставки → COMPLAINT_TIMING. Ошибка только в документах без физического расхождения → DOCUMENTS_REQUESTED. Возврат хорошего товара, который не продаётся → RETURN_REQUESTED.', "cues_prompt_ru" = ARRAY['бой', 'недовложение', 'пересорт', 'не та позиция', 'акт расхождений', 'ТОРГ-2', 'не хватает коробки', 'пришла не та серия']::text[], "synonyms_ru" = '{"chat": ["две упаковки повреждены", "одной кор. не хватает", "привезли не то", "пересорт по плитке", "коробка мокрая, внутри бой", "фото боя скинул", "по накладной 10, по факту 9", "когда замените?", "довезёте недостающее?"], "terms": ["бой", "недовложение", "недостача", "излишек", "пересорт", "акт расхождений", "ТОРГ-2", "приёмка с замечаниями", "корректировочный УПД", "УКД", "отметка в ТТН", "по накладной / по факту"], "business": ["при приёмке выявлено расхождение", "в поставке от 05.11 бой 3 шт.", "недовложение 1 коробки смесителей", "вместо артикула 2021-А пришёл 2022-Б", "составлен акт расхождений", "акт по форме ТОРГ-2 во вложении", "товар принят с замечаниями", "просим допоставить недостающее", "просим заменить разбитые единицы", "просим выставить корректировочный УПД"], "patterns": ["при приёмке + выявлено / обнаружили", "по накладной X, по факту Y", "бой / недовложение / пересорт + число + шт. / кор.", "просим допоставить / заменить / скорректировать"]}'::jsonb, "anti_cues_ru" = '[{"code": "COMPLAINT_QUALITY", "text": "«изделие с заводским дефектом»"}, {"code": "COMPLAINT_TIMING", "text": "«опять опоздали»"}, {"code": "DOCUMENTS_REQUESTED", "text": "«в УПД ошибка в реквизитах» (без физического расхождения)"}, {"code": "DELIVERY_DISCREPANCY_RESOLVED", "text": "«замену получили, вопрос закрыт»"}]'::jsonb, "example_ru" = '«В поставке от 05.11 бой 3 шт. керамогранита, акт расхождений приложили. Когда замените?»', "counter_example_ru" = '«Два насоса из партии не включаются» → это претензия к качеству товара, COMPLAINT_QUALITY.', "note_ru" = 'Closed by: `DELIVERY_DISCREPANCY_RESOLVED` (same topic)
Relations: outranks base `COMPLAINT_QUANTITY` on the same subject (недовложение at acceptance is this code when both are active); leads over `RETURN_REQUESTED` (returning a wrong item is part of the same claim); `both` with `COMPLAINT_ESCALATED`
Deal effect: none; risk trigger «Повторные жалобы» (`REPEATED_COMPLAINTS`)', "updated_at" = now() WHERE "code" = 'DELIVERY_DISCREPANCY';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Обещание закрыть («заменим в пятницу») не закрывает расхождение. Благодарность без подтверждения («спасибо, ждём») → нет сигнала. Закрытие претензии по качеству товара — не этот код (spec §2.1: похвала не закрывает жалобу).', "synonyms_ru" = '{"chat": ["довезли, спасибо, всё ок", "замену получили", "по бою вопросов нет", "всё сошлось", "закрыли", "коробку получили, норм"], "terms": ["УКД подписан", "корректировка проведена", "акт закрыт", "претензий не имеем"], "business": ["замену разбитых единиц получили, претензий нет", "корректировочный УПД подписан", "недостающую коробку получили", "расхождение урегулировано", "акт расхождений закрыт", "возврат принят, документы оформлены", "вопрос по поставке от 05.11 закрыт"], "patterns": ["получили + замену / допоставку / корректировку", "вопрос / расхождение / претензия + закрыт(а)"]}'::jsonb, "anti_cues_ru" = '[{"code": null, "text": "«заменим в пятницу» (наше обещание)"}, {"code": null, "text": "«спасибо, ждём замену»"}, {"code": "FEEDBACK_QUALITY_PRAISE", "text": "«товар отличный, покупатели довольны»"}]'::jsonb, "example_ru" = '«Замену трёх единиц получили, корректировочный УПД подписали. Вопрос по поставке от 05.11 закрыт.»', "updated_at" = now() WHERE "code" = 'DELIVERY_DISCREPANCY_RESOLVED';
--> statement-breakpoint
UPDATE "signal_category" SET "example_ru" = '«Коллеги, направляем протокол встречи от 12.11: согласовали запуск пилота на трёх площадках, следующая встреча — 26.11.»', "updated_at" = now() WHERE "code" = 'DELIVERY_PROTOCOL';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Закрывающие бухгалтерские документы (акт, УПД, счёт-фактура) — не отчёт (DOCUMENTS_REQUESTED). Акт сверки — RECONCILIATION_REQUESTED или нет сигнала. Протокол встречи от клиента — DELIVERY_PROTOCOL. Жалоба «отчёта до сих пор нет» — COMPLAINT_TIMING.', "synonyms_ru" = '{"chat": ["скиньте отчётик за месяц", "где посмотреть результаты?", "нужна статистика по акции", "пришлите цифры по продажам нашей сети"], "terms": ["отчёт", "отчётность", "статистика", "sell-out", "sell-in", "KPI", "итоги"], "business": ["просим предоставить отчёт о проделанной работе за октябрь", "направьте, пожалуйста, итоговый отчёт по проекту", "прошу подготовить отчёт по результатам акции", "необходим отчёт для руководства до", "просим отчёт по исполнению договора"], "patterns": ["«пришлите / подготовьте / предоставьте» + «отчёт / статистику / итоги» + период или проект"]}'::jsonb, "updated_at" = now() WHERE "code" = 'DELIVERY_REPORT_REQUESTED';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["когда привезёте?", "машина сегодня будет?", "во сколько водитель?", "успеете до обеда?", "мы до 12 принимаем", "после 18 никого не будет", "скиньте номер водителя"], "terms": ["окно доставки", "окно приёмки", "рейс", "маршрут", "экспедитор", "водитель", "разгрузка", "пропуск на въезд", "слот на РЦ", "запись на РЦ"], "business": ["просим сообщить дату и время доставки", "уточните, пожалуйста, плановую дату отгрузки по заказу 154", "приёмка товара осуществляется с 9:00 до 12:00", "просим доставить до открытия магазина", "разгрузка только через служебный вход", "нужна доставка к началу монтажа 20.11, успеваете?"], "patterns": ["когда / во сколько + привезёте / доставка / отгрузка / машина", "«принимаем / приёмка + с 9 до 12» и другие конкретные часы"]}'::jsonb, "counter_example_ru" = '«Третий раз за месяц привозите после обеда, у нас срывается монтаж» → это жалоба на сроки, COMPLAINT_TIMING.', "updated_at" = now() WHERE "code" = 'DELIVERY_SCHEDULE_REQUEST';
--> statement-breakpoint
UPDATE "signal_category" SET "label_ru" = 'Запрошены документы (УПД, ТТН, сертификаты, паспорта)', "definition_ru" = 'Клиент просит прислать документы к поставке или на продукцию: УПД, счёт-фактуру, ТОРГ-12, ТТН, сертификаты, декларации соответствия, удостоверения качества, паспорта изделий, копии наших лицензий и разрешений, оригиналы с подписью.', "boundary_ru" = 'Корректировочный документ по расхождению → DELIVERY_DISCREPANCY. Акт сверки → RECONCILIATION_REQUESTED. Прайс или каталог → SALES_PRICE_REQUEST / SALES_CATALOG_REQUESTED. Тендерная документация, которую клиент присылает нам → SALES_TENDER_INVITATION.', "cues_prompt_ru" = ARRAY['пришлите УПД', 'нужны сертификаты', 'декларация соответствия', 'паспорт изделия', 'удостоверение качества', 'оригиналы документов', 'ТОРГ-12', 'счёт-фактура']::text[], "synonyms_ru" = '{"chat": ["скиньте УПД", "нужны серты на кабель", "декларации закиньте", "паспорта на оборудование пришлите", "где оригиналы?", "документы по последней поставке не пришли"], "terms": ["УПД", "ТОРГ-12", "СФ", "счёт-фактура", "ТТН", "серт", "сертификат", "«ДС» (декларация соответствия)", "ЕАЭС", "удостоверение качества", "паспорт изделия", "протокол испытаний", "оригиналы", "ЭДО", "Диадок", "СБИС"], "business": ["просим направить УПД по поставке от 05.11", "для приёмки требуются декларации соответствия", "пришлите, пожалуйста, паспорта качества на партию", "нужны удостоверения качества на новые позиции", "просим оригиналы документов с подписью и печатью", "направьте копии учредительных документов и выписку ЕГРЮЛ", "пришлите счёт-фактуру и ТОРГ-12", "для сети нужен пакет документов на ввод позиций"], "patterns": ["«пришлите / направьте / нужны + название документа» + поставка или позиция"]}'::jsonb, "anti_cues_ru" = '[{"code": "RECONCILIATION_REQUESTED", "text": "«пришлите акт сверки»"}, {"code": "SALES_PRICE_REQUEST", "text": "«пришлите прайс»"}, {"code": "DELIVERY_DISCREPANCY", "text": "«нужен корректировочный УПД на бой»"}]'::jsonb, "example_ru" = '«Для приёмки на РЦ нужны декларации соответствия и паспорта качества на партию от 12.11. Пришлите, пожалуйста, сегодня.»', "note_ru" = 'Closed by: our reply with the documents (Open point 11)
Relations: `DELIVERY_DISCREPANCY` leads over it (a corrected УПД for a discrepancy belongs to that claim); attaches to an open delivery topic of the same shipment; base `CONTRACT_COMPLIANCE_DECLARATION` is separate — this code covers delivery and product documents
Deal effect: none', "updated_at" = now() WHERE "code" = 'DOCUMENTS_REQUESTED';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Клиент просит эксклюзивное право на позицию или бренд: чтобы мы не поставляли её конкурентам в его городе, районе, сегменте или сети, часто как условие ввода в ассортимент или матрицу.', "boundary_ru" = 'Собственная торговая марка (СТМ) по запросу сети — это условия листинга, LISTING_OPPORTUNITY. Жалоба, что позиция есть у соседей дешевле → COMPLAINT_PRICE.', "synonyms_ru" = '{"chat": ["дадите эксклюзив?", "хотим, чтобы это было только у нас", "соседям не возите, ок?", "если эксклюзив — берём", "чтобы в городе больше ни у кого не было"], "terms": ["эксклюзив", "эксклюзивность", "эксклюзивный дистрибутор", "канал", "территория", "СТМ"], "business": ["просим рассмотреть эксклюзивное право на позицию в Санкт-Петербурге", "условием ввода является эксклюзивность в канале сетевой розницы", "готовы взять бренд в ассортимент при условии эксклюзива в районе", "просим не поставлять позицию другим магазинам в нашем районе"], "patterns": ["эксклюзив / эксклюзивность + на позицию / бренд / город / сеть", "не поставляйте + конкурентам / соседям"]}'::jsonb, "anti_cues_ru" = '[{"code": "COMPLAINT_PRICE", "text": "«у соседей эта же позиция дешевле»"}, {"code": "LISTING_OPPORTUNITY", "text": "«нужна СТМ под нашу сеть»"}]'::jsonb, "example_ru" = '«Готовы ввести вашу линейку красок в ассортимент, но при условии эксклюзива в нашем районе — соседям её не поставляйте.»', "counter_example_ru" = '«Эту позицию у вас кто-то ещё в городе берёт?» → вопрос без просьбы об эксклюзиве; нет сигнала.', "note_ru" = 'Статус: proposed (new) · target block after approval: Q
Closed by: `LISTING_CONFIRMED` (same topic) or our reply with the decision
Relevance window: 90 days
Relations: `both` with `LISTING_OPPORTUNITY` (exclusivity as a condition of listing)
Deal effect: stage move: enter «Согласование условий» (S5) on an open listing deal', "updated_at" = now() WHERE "code" = 'EXCLUSIVITY_REQUESTED';
--> statement-breakpoint
UPDATE "signal_category" SET "anti_cues_ru" = '[{"code": null, "text": "«спасибо за ответ» (формула вежливости)"}, {"code": "FEEDBACK_QUALITY_PRAISE", "text": "«товар отличный»"}, {"code": "COMPLAINT_COMM", "text": "«наконец-то ответили»"}]'::jsonb, "updated_at" = now() WHERE "code" = 'FEEDBACK_COMM_PRAISE';
--> statement-breakpoint
UPDATE "signal_category" SET "note_ru" = 'Deal effect: per org rule. Usual: none; may be cited as evidence that the risk «Конкурент предлагает дешевле» is cleared («клиент подтверждает наше предложение»).', "updated_at" = now() WHERE "code" = 'FEEDBACK_PRICE_PRAISE';
--> statement-breakpoint
UPDATE "signal_category" SET "cues_prompt_ru" = ARRAY['клиентам очень понравилось', 'отличное качество', 'всё на высшем уровне', 'очень довольны результатом', 'товар прекрасно зашёл', 'претензий нет, всё идеально', 'превзошли ожидания', 'прекрасная работа']::text[], "synonyms_ru" = '{"chat": ["нашим клиентам очень понравилось", "разлетелось на ура", "огонь!", "супер, всё чётко", "шикарно получилось", "топ"], "terms": ["качество", "результат", "без замечаний"], "business": ["благодарим за качественно выполненную работу", "результат полностью соответствует ожиданиям", "отмечаем высокое качество продукции", "руководство высоко оценило результат"], "patterns": ["очень понравилось / понравился / понравилась", "«отличное / прекрасное» + качество / результат", "благодарим за качественно"]}'::jsonb, "anti_cues_ru" = '[{"code": null, "text": "«спасибо, получили»"}, {"code": "FEEDBACK_COMM_PRAISE", "text": "«Анна всегда быстро отвечает, спасибо»"}, {"code": "ORDER_REQUESTED", "text": "«покупателям понравилось, давайте ещё 10 коробок»"}]'::jsonb, "example_ru" = '«Хотим сказать спасибо за оборудование для нового цеха — работает без сбоев, особенно довольны упаковочной линией.»', "updated_at" = now() WHERE "code" = 'FEEDBACK_QUALITY_PRAISE';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["дал ваш номер знакомому снабженцу", "скинула ваш контакт подруге, у неё своё производство", "вас советуют", "наберите Ивану, он ждёт звонка", "добавила вас в чат с"], "terms": ["рекомендация", "реферал", "интро", "тёплый контакт"], "business": ["рекомендовали вашу компанию нашим партнёрам", "передали ваши контакты в", "позвольте представить вам", "знакомлю вас с коммерческим директором", "к вам обратится наш партнёр, он в курсе", "нам вас рекомендовала компания"], "patterns": ["«рекомендовал(а) вас» + кому", "«передал ваш контакт» + кому", "«знакомлю вас с» + человек", "«вас нам рекомендовал(а)» + кто"]}'::jsonb, "example_ru" = '«Рекомендовали вас нашим партнёрам из строительной компании, передала ваш контакт их директору по закупкам — он напишет на этой неделе.»', "updated_at" = now() WHERE "code" = 'FEEDBACK_REFERRAL';
--> statement-breakpoint
UPDATE "signal_category" SET "example_ru" = '«Цена «Перчатки нитриловые, 100 шт.» снижена с 1 120 ₽ до 990 ₽ (−11,6 %) с 15.11.2026.»', "counter_example_ru" = '«Клиенту ООО «Лаванда» установлена скидка 7 %» → индивидуальная скидка, нет сигнала.', "updated_at" = now() WHERE "code" = 'INTERNAL_PRICE_CHANGE';
