UPDATE "signal_category" SET "definition_ru" = 'Наша позиция каталога сменила статус: введена новая позиция, позиция выведена из ассортимента, закончилась на складе или снова появилась в наличии, сменилась версия или модификация.', "example_ru" = '«Остаток «Картридж фильтра ФК-10» — 0 шт. с 12.11.2026; за 90 дней позицию заказывали 3 клиента.»', "counter_example_ru" = '«Остаток «Картридж фильтра ФК-10» снизился со 120 до 96 шт.» → обычное движение склада, нет сигнала.', "updated_at" = now() WHERE "code" = 'INTERNAL_PRODUCT_STATUS_UPDATE';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Входящий счёт поставщика НАМ — не этот код. Счёт ещё не просрочен и вопросов нет — нет сигнала. Клиент обещает оплатить к дате — PAYMENT_PROMISE на той же теме; если этот код в организации не включён — контекст к этому коду. Запрос акта сверки без долга — RECONCILIATION_REQUESTED. Просьба об отсрочке на будущее — PAYMENT_TERMS_REQUEST / SALES_RENEGOTIATION.', "note_ru" = 'Closed by: `INVOICE_PAID`
Relations: — in v204. Agency: one card with `INVOICE_DISPUTE_RAISED` (a dispute does not replace the overdue fact, Maslov §5.5). `PAYMENT_PROMISE` attaches to this topic.
Deal effect: per org rule. Possible: risk trigger «Долг клиента» (open deal of this client); clears with `INVOICE_PAID` or a kept `PAYMENT_PROMISE`.', "updated_at" = now() WHERE "code" = 'INVOICE_OVERDUE';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Обещание оплатить — не оплата (PAYMENT_PROMISE). Урегулирование спора без оплаты — не этот код (агентский INVOICE_DISPUTE_RESOLVED). Наша оплата поставщику — не этот код. Частичная оплата закрывает только оплаченную часть: если долг остаётся, INVOICE_OVERDUE остаётся открытым.', "note_ru" = 'Display profile: S0 (state code, closes and makes no card)
Closes: `INVOICE_OVERDUE` (same client / invoice topic)
Deal effect: per org rule. Clears the risk «Долг клиента» where an org uses it. Payment is a separate fact, never a stage move.', "updated_at" = now() WHERE "code" = 'INVOICE_PAID';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Клиент подтверждает решение в нашу пользу: наши позиции утверждены в ассортимент или ассортиментную матрицу, нас выбрали поставщиком (в том числе по итогам тендера), договор поставки подписан, позиции остаются после пересмотра.', "cues_prompt_ru" = ARRAY['утвердили в ассортимент', 'ввели в ассортимент', 'прошли комитет', 'вы выбраны поставщиком', 'договор подписан', 'позиции остаются', 'признаны победителем', 'включили в матрицу']::text[], "synonyms_ru" = '{"chat": ["комитет прошли", "берём в ассортимент все три", "утвердили, с понедельника в каталоге", "вы в матрице", "договор подписали", "оставляем вашу продукцию", "победили, поздравляю"], "terms": ["ввод", "утверждено", "комитет", "АМ", "SKU", "протокол подведения итогов", "победитель закупки", "договор подписан"], "business": ["по итогам закупочного комитета позиции утверждены к вводу", "ваши позиции включены в новый каталог с 1 декабря", "сообщаем, что вы выбраны поставщиком по категории электротоваров", "по итогам закупки ваша заявка признана победителем", "договор поставки подписан, оригинал направим почтой", "после пересмотра матрицы ваши позиции сохраняются", "согласовали ввод трёх SKU в 40 магазинов"], "patterns": ["«утвердили / ввели / включили / выбрали / подписали» + позиции / поставщика / договор", "позиции + остаются / сохраняются"]}'::jsonb, "note_ru" = 'Статус: proposed (new) · target block after approval: Q
Display profile: S1 — updates the linked card and the deal; no own card (if nothing is linked → W1 info)
Closes: `LISTING_OPPORTUNITY`, `NEW_VENUE_OPENING`, `DELISTING_RISK`, `EXCLUSIVITY_REQUESTED` on the same topic
Relations: attaches to the listing / new-location / tender / contract topic of the same client; never creates a topic by itself (spec §2.1 rule 6)
Deal effect: outcome `won` for `listing`, `new_location`, `tender`, `supply_agreement`, `renewal`; clears risks `DELISTING`, `COMPETITOR_PRICE`, `CONTRACT_EXPIRING_NO_RENEWAL`', "updated_at" = now() WHERE "code" = 'LISTING_CONFIRMED';
--> statement-breakpoint
UPDATE "signal_category" SET "label_ru" = 'Возможность ввода в ассортимент клиента', "definition_ru" = 'Клиент сообщает, что обновляет ассортимент, ассортиментную матрицу, каталог или полку, и рассматривает наши позиции для ввода; или прямо зовёт нас предложить позиции на листинг.', "boundary_ru" = 'Разовый заказ новой позиции без слов об ассортименте или матрице → ORDER_REQUESTED. Просьба прайса без повода → SALES_PRICE_REQUEST. Тендер или формальная закупка с документацией → SALES_TENDER_INVITATION. Клиент уже подтвердил ввод → LISTING_CONFIRMED (предложено). Общие слова «будем рады сотрудничеству» без пересмотра ассортимента или матрицы → нет сигнала.', "cues_prompt_ru" = ARRAY['обновляем ассортимент', 'ввод в ассортимент', 'листинг', 'рассматриваем ваши позиции', 'пересматриваем матрицу', 'новый каталог с весны', 'ищем новые позиции в категорию', 'закупочный комитет']::text[], "synonyms_ru" = '{"chat": ["переделываем ассортимент, что можете предложить?", "нужно пару позиций в эконом-сегмент", "будем менять основного поставщика по категории", "скоро комитет, закиньте позиции", "хотим вашу линейку в каталог", "ищем новинки к сезону", "есть место на полке под новую категорию"], "terms": ["листинг", "ввод", "матрица", "«АМ» (ассортиментная матрица)", "СТМ", "полка", "планограмма", "закупочный комитет", "каталог", "ассортиментная линейка", "базовый ассортимент", "новинки", "категорийный менеджер", "КМ"], "business": ["планируем обновление ассортимента к весеннему сезону", "рассматриваем ввод новых позиций в ассортимент", "формируем ассортиментную матрицу на 2026 год", "приглашаем представить позиции на закупочный комитет", "ищем поставщика по категории сантехники", "готовы рассмотреть ваши позиции для ввода в сеть", "пересмотр полки по категории «инструмент»", "нужны 3–4 позиции в сегменте до 1500 ₽ на полке", "расширяем раздел импортных позиций в каталоге"], "patterns": ["обновляем / пересматриваем / формируем + каталог / матрицу / ассортимент", "рассматриваем / готовы ввести + ваши позиции", "предложите + позиции + для каталога / для сети"]}'::jsonb, "anti_cues_ru" = '[{"code": "ORDER_REQUESTED", "text": "«пришлите 2 кор. новой модели»"}, {"code": "SALES_TENDER_INVITATION", "text": "«объявлен тендер на поставку оборудования»"}, {"code": "LISTING_CONFIRMED", "text": "«ваши позиции утвердили в ассортимент»"}, {"code": "DELISTING_RISK", "text": "«убираем вашу продукцию из ассортимента»"}]'::jsonb, "example_ru" = '«Мы обновляем ассортимент к весеннему сезону и рассматриваем ваши позиции по садовому инструменту и поливу. Пришлите подборку и условия до 25.11.»', "counter_example_ru" = '«Прорабу нужен новый герметик, привезите коробку на объект» → разовый заказ без пересмотра ассортимента; это ORDER_REQUESTED.', "note_ru" = 'Closed by: `LISTING_CONFIRMED` (proposed, same topic); `SALES_OFFER_DECLINED` ends it as a loss
Relevance window: 90 days — assortment reviews run for weeks
Relations: `both` with `SAMPLES_REQUESTED`, `PROMO_SUPPORT_REQUESTED`; `both` with `NEW_VENUE_OPENING` (one topic; the deal type then is `new_location`); `both` with `SALES_OFFER_REQUESTED`
Deal effect: deal entry: `listing` (listing in the client''s assortment); in-stage context on an open deal of the same type', "updated_at" = now() WHERE "code" = 'LISTING_OPPORTUNITY';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Перенос на конкретную новую дату — не этот код (если дата далеко — MEETING_DELAYED). Отмена с нашей стороны — не сигнал. Автоматический ответ календаря «Отклонено» без слов клиента — обрабатывает детерминированный фильтр; код ставить, только если ясно, что встреча отменена. Отмена демонстрации или презентации — этот код, если это встреча с клиентом.', "note_ru" = 'Closed by: — (a new agreed date makes it context)
Deal effect: per org rule, e.g. postponement event for the risk «Решение откладывается» (fires from the 2nd distinct postponement of the same decision with no new date and next step, Q24-3). Agency: risk «Снижение вовлечённости» (Maslov risk 21).', "updated_at" = now() WHERE "code" = 'MEETING_CANCEL';
--> statement-breakpoint
UPDATE "signal_category" SET "note_ru" = 'Date gate: { fact: `proposedMeetingDate`, test: more than N days after the item, setting: `cards.meetingDelayedMinDays`, window: 28 }
Deal effect: per org rule, e.g. postponement event for the risk «Решение откладывается» (2nd distinct postponement, Q24-3).', "updated_at" = now() WHERE "code" = 'MEETING_DELAYED';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Клиент приглашает на встречу или приводит на неё человека со своей стороны, которого раньше не было в общении (руководитель, закупщик, финансист, главный инженер).', "synonyms_ru" = '{"chat": ["возьму с собой главного инженера", "будет наш новый руководитель склада", "подтяну на созвон директора", "с нами ещё Олег из закупок"], "terms": ["участники встречи", "приглашение", "ЛПР", "ФД", "КД", "закупщик"], "business": ["на встрече со стороны компании также будет присутствовать коммерческий директор", "добавила в приглашение руководителя отдела закупок", "к обсуждению присоединится наш финансовый директор", "прошу учесть, что на встрече будет новый управляющий"], "patterns": ["«на встрече будет / присоединится / подключу» + новый человек с ролью"]}'::jsonb, "updated_at" = now() WHERE "code" = 'MEETING_NEW_STAKEHOLDER';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Срочная встреча из-за проблемы, ошибки или конфликта — MEETING_URGENT_ISSUE. Обычное приглашение на встречу через 1–3 недели — нет сигнала. Просьба прислать образцы — SAMPLES_REQUESTED (если вместе со срочной встречей — оба кода).', "anti_cues_ru" = '[{"code": "MEETING_URGENT_ISSUE", "text": "«срочно нужна встреча, у нас пропал товар с полки»"}, {"code": null, "text": "«давайте в конце месяца пересечёмся»"}, {"code": "SAMPLES_REQUESTED", "text": "«пришлите образцы до запуска»"}]'::jsonb, "example_ru" = '«Открываем новую точку раньше плана — можете завтра подъехать и обсудить ассортимент?»', "updated_at" = now() WHERE "code" = 'MEETING_URGENT';
--> statement-breakpoint
UPDATE "signal_category" SET "counter_example_ru" = '«Есть идея по новой линейке, давайте завтра обсудим» → интерес, MEETING_URGENT.', "updated_at" = now() WHERE "code" = 'MEETING_URGENT_ISSUE';
--> statement-breakpoint
UPDATE "signal_category" SET "note_ru" = 'Статус: proposed (new) · target block after approval: O
Closed by: `ORDER_CONFIRMED` (same topic) or our reply
Relevance window: 14 days
Relations: attaches to the order topic; base `COMPLAINT_PRICE` outranks it when the client complains about the delivery fee as a price
