UPDATE "signal_category" SET "label_ru" = 'Клиент открывает новую точку / филиал', "definition_ru" = 'Клиент сам сообщает, что открывает новый филиал, магазин, склад, производство, офис или новую точку сети, и это повод для поставок туда.', "cues_prompt_ru" = ARRAY['открываем второй филиал', 'новая точка', 'новый магазин', 'открытие в марте', 'запускаем новый проект', 'ещё один склад', 'новое производство', 'будем открываться']::text[], "synonyms_ru" = '{"chat": ["открываем ещё одно место", "у нас новый проект, будем открываться", "запускаем цех, нужно оснащение", "новая точка на Петроградке", "скоро открытие, надо всё закупить", "делаем второй магазин"], "terms": ["открытие", "новая точка", "новый объект", "пробный запуск", "запуск проекта", "стартовая закупка", "подготовка к запуску"], "business": ["в марте открываем второй филиал в Новосибирске", "планируется открытие нового магазина сети в Казани", "запускаем новый производственный участок", "открываем склад в Подмосковье", "нужен поставщик для нового объекта", "новая точка начнёт работу с 1 декабря", "готовим к открытию сервисный центр", "объект открывается весной, хотим обсудить ассортимент поставок"], "patterns": ["открываем / запускаем / будем открывать + филиал / магазин / склад / точку / проект", "срок открытия («в марте», «к Новому году»)"]}'::jsonb, "anti_cues_ru" = '[{"code": null, "text": "«читали, что вы открываете пять филиалов?» (наш вопрос по слухам)"}, {"code": "SIGNAL_EXPANSION", "text": "новость «сеть открывает пять магазинов» из веб-поиска"}, {"code": null, "text": "«переезжаем на новый адрес, доставка теперь туда»"}, {"code": null, "text": "«закрываемся на ремонт на две недели»"}]'::jsonb, "example_ru" = '«Открываем второй филиал в марте, хотим обсудить ассортимент и стартовую закупку.»', "card_note_ru" = 'Пишите «Ответственный менеджер — договориться с клиентом о встрече по ассортименту и стартовой закупке новой точки»; укажите дату открытия, если она названа.', "updated_at" = now() WHERE "code" = 'NEW_VENUE_OPENING';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Перенос даты («перенесите на следующую неделю») → ORDER_CHANGE_REQUESTED. Удаление одной позиции → ORDER_CHANGE_REQUESTED. Отказ от нового предложения, а не от заказа → SALES_OFFER_DECLINED. Отказ от наших позиций в ассортименте вообще → DELISTING_RISK. Отказ принять доставку из-за боя или пересорта → DELIVERY_DISCREPANCY / RETURN_REQUESTED.', "synonyms_ru" = '{"chat": ["отбой по заказу", "не везите", "заказ не нужен", "снимите заказ", "отменяем всё", "пока ничего не надо, отбой", "не грузите, мы передумали", "сорри, отмена"], "terms": ["аннулирование заказа", "снятие резерва", "отмена заявки", "отказ от поставки"], "business": ["просим отменить заказ № 154", "прошу аннулировать заявку", "заказ больше не актуален", "отзываем заявку на поставку", "просим не осуществлять отгрузку", "в связи с закрытием филиала заказ отменяем", "счёт оплачивать не будем, заказ отменён", "просим снять резерв"], "patterns": ["отменяем / аннулируем / отзываем + заказ / заявку", "не + отгружайте / везите / грузите"]}'::jsonb, "anti_cues_ru" = '[{"code": "ORDER_CHANGE_REQUESTED", "text": "«перенесите на вторник»"}, {"code": "ORDER_CHANGE_REQUESTED", "text": "«уберите из заказа кронштейны»"}, {"code": "SALES_OFFER_DECLINED", "text": "«предложение не подходит»"}, {"code": "DELISTING_RISK", "text": "«выводим вашу продукцию из ассортимента»"}]'::jsonb, "example_ru" = '«Коллеги, заказ на пятницу отменяем, монтаж на объекте перенесли. Не отгружайте, пожалуйста.»', "counter_example_ru" = '«Монтаж перенесли, отгрузку сдвиньте на 20-е» → заказ остаётся, меняется дата; это ORDER_CHANGE_REQUESTED.', "updated_at" = now() WHERE "code" = 'ORDER_CANCELLED';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Клиент просит изменить уже отправленный заказ: добавить или убрать позицию, поменять количество, заменить позицию на другую, перенести дату или адрес отгрузки.', "boundary_ru" = 'Новый отдельный заказ на другие позиции или другую дату → ORDER_REQUESTED. Полная отмена → ORDER_CANCELLED. Перенос отгрузки — это изменение, а не отмена. Просьба подобрать замену позиции, которой нет у нас на складе → SUBSTITUTION_REQUESTED (предложено). Жалоба на уже доставленный товар → блок R.', "cues_prompt_ru" = ARRAY['добавьте в заказ', 'уберите позицию', 'замените на', 'перенесите отгрузку', 'вместо 12 сделайте 8', 'докиньте упаковку', 'поменяйте адрес доставки', 'скорректируйте заявку']::text[], "synonyms_ru" = '{"chat": ["докиньте ещё упаковку саморезов", "уберите кронштейны", "вместо 12 сделайте 8", "давайте не в пятницу, а в субботу", "в заказ ещё 2 паллеты плитки", "поменяйте на белый цвет", "минус одна упаковка", "закиньте ещё позицию, плиз", "привезите не на Тверскую, а на Арбат"], "terms": ["корректировка заказа", "новая редакция заявки", "доп. позиция", "перенос отгрузки", "изменение адреса доставки"], "business": ["просим внести изменения в заказ", "прошу скорректировать заявку № 154", "прошу исключить из заказа позицию", "просим увеличить количество", "прошу заменить модель А200 на А300", "прошу перенести отгрузку на понедельник", "доставку просим перенести на другой адрес", "уточнение к заказу", "прошу считать актуальной заявку во вложении"], "patterns": ["«добавьте / уберите / замените / перенесите» + ссылка на существующий заказ («в заказ», «к заявке», «в сегодняшнюю отгрузку»)"]}'::jsonb, "anti_cues_ru" = '[{"code": "ORDER_REQUESTED", "text": "«и ещё отдельный заказ на следующую среду»"}, {"code": "ORDER_CANCELLED", "text": "«отгрузку не делайте, заказ отменяем»"}, {"code": "SUBSTITUTION_REQUESTED", "text": "«фильтров нет, чем можно заменить?»"}, {"code": "DELIVERY_DISCREPANCY", "text": "«привезли не ту позицию»"}]'::jsonb, "example_ru" = '«По заявке 154: фильтры вместо 12 сделайте 8 упак. и добавьте 2 упак. уплотнителей. Отгрузку перенесите на понедельник.»', "updated_at" = now() WHERE "code" = 'ORDER_CHANGE_REQUESTED';
--> statement-breakpoint
UPDATE "signal_category" SET "note_ru" = 'Display profile: S0 — closes, no card
Emitted by: both — parser (our outbound mail / chat) now; process (order status `confirmed` in the CRM, no LLM) in the orders step
Closes: `ORDER_REQUESTED`, `ORDER_CHANGE_REQUESTED` on the same topic; after approval of block U also `PREORDER_REQUESTED`, `SUBSTITUTION_REQUESTED`, `MIN_ORDER_ISSUE`
Relations: attaches to the order topic by order / invoice number; never creates a topic (spec §6.2 step 6)
Deal effect: none (Q26)', "updated_at" = now() WHERE "code" = 'ORDER_CONFIRMED';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Клиент (закупщик, менеджер по закупкам, управляющий, снабженец) присылает заказ на поставку: называет позиции и количество (штуки, упаковки, паллеты) и просит отгрузить, привезти или выставить счёт. Сюда же относится повтор прошлого заказа («как обычно», «как в прошлый раз») и заявка файлом.', "boundary_ru" = 'Вопрос о цене или наличии без просьбы отгрузить → SALES_PRICE_REQUEST / STOCK_AVAILABILITY_REQUEST. Изменение уже отправленного заказа → ORDER_CHANGE_REQUESTED. Бронь товара, которого ещё нет (новая партия, будущий контейнер) → PREORDER_REQUESTED (предложено). Наше собственное предложение, наша заявка поставщику, подтверждение заказа от нашего поставщика нам (мы покупатель → блок N). Напоминание по уже отправленному заказу («подтвердите, что заявку получили») — не новый код, а обновление той же темы.', "cues_prompt_ru" = ARRAY['прошу отгрузить', 'заказ на', 'нужно 12 упаковок', 'по 10 шт.', 'выставьте счёт на', 'сделайте заявку', 'закажем как обычно', 'закиньте в заказ']::text[], "synonyms_ru" = '{"chat": ["закиньте в заказ", "скиньте счёт на", "нам на пятницу", "привезите", "закажем как обычно", "как в прошлый раз, только перчаток побольше", "давайте 2 паллеты цемента и мешок затирки", "плиз, на завтра", "оформите нам", "надо 6 шт. картриджей до выходных", "запишите на четверг", "берём"], "terms": ["кор.", "упак.", "шт.", "пал.", "компл.", "м", "т", "арт.", "артикул", "код товара", "партия", "серия", "заявка", "счёт на оплату", "спецификация к заказу"], "business": ["прошу отгрузить", "просим поставить", "направляем заказ", "заявка на поставку", "заказ на следующую неделю", "прошу выставить счёт на следующие позиции", "прошу зарезервировать и отгрузить", "просим доставить к пятнице", "во вложении заявка", "повторите, пожалуйста, прошлый заказ", "прошу включить в ближайшую отгрузку", "просим привезти по адресу склада на Покровке"], "patterns": ["«прошу / просим + отгрузить / поставить / привезти» + список позиций с количеством", "нужно / надо + число + шт. / упак. / кор.", "«на + день недели / дату» (желаемый срок)", "таблица «наименование — количество» во вложении или в теле"]}'::jsonb, "anti_cues_ru" = '[{"code": "STOCK_AVAILABILITY_REQUEST", "text": "«есть ли насосы этой серии?»"}, {"code": "SALES_PRICE_REQUEST", "text": "«пришлите прайс»"}, {"code": "ORDER_CHANGE_REQUESTED", "text": "«добавьте ещё упаковку к заказу»"}, {"code": "ORDER_CONFIRMED", "text": "«заказ подтверждаем, счёт во вложении» (наше письмо)"}, {"code": "LISTING_OPPORTUNITY", "text": "«готовы взять в ассортимент три позиции»"}, {"code": "PREORDER_REQUESTED", "text": "«поставьте нас в лист ожидания на новую партию»"}]'::jsonb, "example_ru" = '«Добрый день! Прошу отгрузить к пятнице: перчатки нитриловые M — 12 кор. по 100 шт., маски медицинские — 3 кор. Счёт на ООО «Ромашка».»', "counter_example_ru" = '«Подскажите, почём сейчас перчатки нитриловые M и сколько их у вас на складе?» → нет просьбы отгрузить; это вопрос о цене и наличии.', "note_ru" = 'Display profile: from weight (D4) + deadline escalation: same-day shipment → «Сейчас» (decided R8, 2026-11-13)
Closed by: `ORDER_CONFIRMED` (same topic); made moot by `ORDER_CANCELLED` (Open point 11)
Relevance window: 14 days — an order that is not confirmed in 14 days was processed outside the CRM or is lost; the card must not stay open longer
Relations: outranks `STOCK_AVAILABILITY_REQUEST` and `SALES_PRICE_REQUEST` on the same subject; `ORDER_CANCELLED` outranks it; replaces base `SALES_BOOKING_RECEIVED` (an org activates one of the two)
Deal effect: none (Q26). Topic and card only. Later step: «Создать заказ» on the card (replaces the `new_order` card)', "updated_at" = now() WHERE "code" = 'ORDER_REQUESTED';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Производитель, которого мы представляем, другой партнёр или его продукт получает награду, высокую оценку экспертов или место в рейтинге — аргумент для продаж.', "cues_prompt_ru" = ARRAY['золотая медаль', 'высшая оценка экспертов', 'лучший продукт года', 'вошёл в топ', 'победитель конкурса', 'гран-при', 'премия выставки']::text[], "synonyms_ru" = '{"chat": ["наш насос взял золото на выставке", "высший балл у экспертов"], "terms": ["медаль", "балл", "рейтинг"], "business": ["удостоен золотой медали", "получил высшую оценку жюри"]}'::jsonb, "anti_cues_ru" = '[{"code": "COMPETITOR_AWARD", "text": "«продукт Альянса получил золото»"}]'::jsonb, "example_ru" = '«Насос серии «Сигма-200» завода «Сигма», который мы представляем, получил золотую медаль на международной выставке.»', "counter_example_ru" = '«Клиент получил отраслевую премию» → SIGNAL_AWARD.', "card_note_ru" = 'Назвать продукт и награду; шаг — использовать как аргумент в следующих предложениях клиентам.', "updated_at" = now() WHERE "code" = 'PARTNER_AWARD';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Партнёр расширяется: новые производственные площадки, рост производства, новый склад или регион у логистического партнёра, новая команда.', "cues_prompt_ru" = ARRAY['расширяет производство', 'новая производственная площадка', 'открыл склад', 'новый регион доставки', 'увеличил мощности', 'новый производственный цех']::text[], "synonyms_ru" = '{"chat": ["завод запустил вторую линию", "логист открыл терминал в Новосибе"], "terms": ["площадка", "мощности", "терминал", "линия"], "business": ["ввод новых производственных мощностей", "расширение производственных площадей"]}'::jsonb, "anti_cues_ru" = '[{"code": "COMPETITOR_EXPANSION", "text": "«ТехноАльянс открыл склад»"}]'::jsonb, "counter_example_ru" = '«Наш клиент открывает филиал в Новосибирске» → NEW_VENUE_OPENING.', "updated_at" = now() WHERE "code" = 'PARTNER_EXPANSION';
--> statement-breakpoint
UPDATE "signal_category" SET "cues_prompt_ru" = ARRAY['новый владелец', 'приобрёл завод', 'вошёл в капитал', 'привлёк инвестиции', 'сменил собственника', 'сделка по покупке']::text[], "synonyms_ru" = '{"chat": ["завод купил холдинг", "у производителя новый хозяин"], "terms": ["доля", "бенефициар", "холдинг"], "business": ["завершена сделка по приобретению производственной компании", "смена конечного бенефициара"]}'::jsonb, "anti_cues_ru" = '[{"code": "COMPETITOR_FUNDING", "text": "«ТехноАльянс купили»"}]'::jsonb, "example_ru" = '«Завод «Сигма» перешёл под контроль промышленного холдинга, договоры дистрибуции будут пересмотрены.»', "counter_example_ru" = '«Завод «Сигма» открыл новый производственный цех» → PARTNER_EXPANSION.', "updated_at" = now() WHERE "code" = 'PARTNER_FUNDING';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["у завода скандал с подделкой", "их запретили ввозить", "партию отзывают"], "terms": ["РПН", "декларация соответствия", "отзыв", "санкции"], "business": ["Роспотребнадзор приостановил ввоз", "выявлено несоответствие", "отзыв продукции с рынка"]}'::jsonb, "example_ru" = '«Роспотребнадзор приостановил ввоз продукции завода «Сигма» из-за несоответствия маркировки.»', "counter_example_ru" = '«Поставка от завода «Сигма» сдвигается на две недели» → SUPPLIER_DELIVERY_DELAY.', "updated_at" = now() WHERE "code" = 'PARTNER_NEGATIVE_PRESS';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["наш логист взял ещё сеть", "завод зашёл в федеральную сеть"], "terms": ["контракт", "тендер", "листинг"], "business": ["заключено соглашение о поставках", "определён победителем закупки"]}'::jsonb, "anti_cues_ru" = '[{"code": "COMPETITOR_NEW_CLIENT", "text": "«ТехноАльянс выиграл тендер»"}]'::jsonb, "example_ru" = '«Наш транспортный партнёр «СеверЛогистик» заключил контракт на доставку для крупной торговой сети.»', "counter_example_ru" = '«ООО «ТехноАльянс» заключило контракт с торговой сетью» → COMPETITOR_NEW_CLIENT.', "updated_at" = now() WHERE "code" = 'PARTNER_NEW_CLIENT';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'У партнёра меняется руководство или ключевой контакт: экспорт-менеджер производителя, главный технолог, директор логистической компании.', "cues_prompt_ru" = ARRAY['новый экспорт-менеджер', 'новый главный технолог', 'назначен директором', 'покидает компанию', 'теперь ваш контакт', 'сменился менеджер по России']::text[], "synonyms_ru" = '{"chat": ["у завода новый экспорт-менеджер", "Марко ушёл, теперь Лука"], "terms": ["экспорт-менеджер", "технолог", "KAM"], "business": ["сообщаем о назначении", "с 1 декабря по всем вопросам обращайтесь к"]}'::jsonb, "example_ru" = '«С 1 декабря экспорт-менеджером завода по России назначен новый сотрудник, прежний покидает компанию.»', "counter_example_ru" = '«У клиента сменился закупщик» → CONTACT_NEW_DECISION_MAKER.', "updated_at" = now() WHERE "code" = 'PARTNER_PERSONNEL';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Производитель, которого мы представляем, или другой партнёр выпускает новый продукт: новую модель, новую версию, линейку, лимитированную серию, новую услугу.', "cues_prompt_ru" = ARRAY['новая модель', 'новая версия продукта', 'выпускает новую линейку', 'новинка от производителя', 'первая партия', 'лимитированный выпуск', 'старт продаж новинки']::text[], "synonyms_ru" = '{"chat": ["завод выпустил новую модель", "пришла новая версия", "у них теперь компактная серия"], "terms": ["модель", "версия", "линейка", "лимитка"], "business": ["рады представить новую модель", "презентация новой линейки", "старт продаж лимитированной серии"]}'::jsonb, "anti_cues_ru" = '[{"code": "SUPPLIER_PRICE_CHANGE", "text": "«с 01.12 новые цены на серию 2027»"}]'::jsonb, "example_ru" = '«Завод «Сигма» выпускает первую серию частотных преобразователей, старт продаж в феврале.»', "counter_example_ru" = '«Завод «Сигма» повышает цены с 1 февраля» → SUPPLIER_PRICE_CHANGE.', "card_note_ru" = 'Назвать партнёра, продукт и дату старта; шаг — решить, предлагать ли новинку клиентам, у которых эта категория в закупке.', "updated_at" = now() WHERE "code" = 'PARTNER_PRODUCT_NEW';
--> statement-breakpoint
UPDATE "signal_category" SET "example_ru" = '«Для открытия второго филиала просим увеличить кредитный лимит до 1,5 млн ₽ и отсрочку до 30 календарных дней.»', "note_ru" = 'Closed by: our reply with agreed terms (Open point 11)
Relations: `both` with base `SALES_RENEGOTIATION` (price and payment terms in one message = two codes; payment terms only = this code only); `both` with `NEW_VENUE_OPENING` (terms for a new location)
Deal effect: stage move: enter «Согласование условий» (S5) on an open `new_location` / `listing` / `supply_agreement` / `renewal` deal; risk trigger «Жёсткие условия оплаты» (`PAYMENT_TERMS_ABOVE_POLICY`)', "updated_at" = now() WHERE "code" = 'PAYMENT_TERMS_REQUEST';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Клиент бронирует товар, которого ещё нет на складе: новую партию, будущий контейнер, сезонную позицию (новогодний ассортимент, летнюю линейку), и называет количество.', "boundary_ru" = 'Заказ товара в наличии → ORDER_REQUESTED. Вопрос «когда будет поступление» без брони → STOCK_AVAILABILITY_REQUEST.', "cues_prompt_ru" = ARRAY['предзаказ', 'забронируйте', 'поставьте нас в лист ожидания', 'как только придёт, отгрузите', 'на новую партию', 'из следующего контейнера', 'зарезервируйте под нас', 'под новогодний сезон']::text[], "synonyms_ru" = '{"chat": ["забейте нам 5 кор. с нового завоза", "как приедет — сразу к нам", "на нас отложите", "впишите в предзаказ", "новую серию бронируем"], "terms": ["предзаказ", "бронь", "резерв под поступление", "лист ожидания", "транзит", "из контейнера", "сезонная позиция"], "business": ["просим принять предзаказ на 60 шт. из партии 2025 года", "зарезервируйте, пожалуйста, 10 кор. из ближайшего поступления", "по поступлению просим сразу отгрузить", "бронируем новогодний ассортимент на декабрь", "просим включить нас в предзаказ на новую модель"], "patterns": ["забронируйте / зарезервируйте / предзаказ + количество + из будущего поступления / новой партии"]}'::jsonb, "anti_cues_ru" = '[{"code": "ORDER_REQUESTED", "text": "«отгрузите 5 кор. в пятницу» (товар есть)"}, {"code": "STOCK_AVAILABILITY_REQUEST", "text": "«когда придёт новая партия?»"}]'::jsonb, "example_ru" = '«Поставьте нас в предзаказ на новую модель котлов: 10 шт., отгрузка сразу по приходу.»', "counter_example_ru" = '«Новая модель котлов в этом году будет?» → бронирования нет.', "note_ru" = 'Статус: proposed (new) · target block after approval: O
Closed by: `ORDER_CONFIRMED` (same topic: the booking is confirmed)
Relevance window: until the expected arrival date if known, else default
Relations: outranks `STOCK_AVAILABILITY_REQUEST` on the same subject
Deal effect: none (Q26: an order-type code)', "updated_at" = now() WHERE "code" = 'PREORDER_REQUESTED';
--> statement-breakpoint
