UPDATE "signal_category" SET "boundary_ru" = 'Только недовольство ценой без просьбы изменить условия — COMPLAINT_PRICE (бывают вместе). Первый запрос цены — SALES_PRICE_REQUEST. Просьба об отсрочке, лимите или работе без предоплаты — PAYMENT_TERMS_REQUEST, не этот код. Торг по ещё не согласованному КП — SALES_OFFER_REQUESTED / агентский PITCH_FINAL_TERMS_DISCUSSION.', "synonyms_ru" = '{"chat": ["давайте пересоберём условия", "можно скидку побольше?", "нам надо дешевле, иначе не потянем", "давайте пересмотрим бонус", "поднимите скидку до 15"], "terms": ["скидка", "ретро-бонус", "бонус за объём", "«отсрочка платежа» (если не включён PAYMENT_TERMS_REQUEST)", "фиксация цен", "ДС об изменении условий"], "business": ["просим пересмотреть условия договора", "предлагаем обсудить изменение коммерческих условий", "рассчитываем на увеличение скидки при сохранении объёмов", "просим зафиксировать цены на 2027 год", "готовы продлить при условии снижения цены", "просим изменить порядок оплаты"], "patterns": ["«пересмотреть / изменить / обсудить» + «условия / скидку / цены»", "«при условии» + «снижения / увеличения»"]}'::jsonb, "note_ru" = 'Relations: — in v204. Often together with `COMPLAINT_PRICE` (complaint + request).
Deal effect: per org rule. Possible: risk trigger «Конкурент предлагает дешевле» (not at the first-contact stage) and a postponement event for «Решение откладывается» (2nd distinct postponement, Q24-3).', "updated_at" = now() WHERE "code" = 'SALES_RENEGOTIATION';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["у нас тендер на поставку оборудования, будете участвовать?", "скинула ссылку на закупку", "запускаем отбор поставщиков, хотите поучаствовать?", "закупка висит на площадке до пятницы"], "terms": ["44-ФЗ", "223-ФЗ", "НМЦК", "НМЦД", "ЕИС", "zakupki.gov.ru", "ЭТП", "РТС-тендер", "Сбербанк-АСТ", "B2B-Center", "запрос котировок", "запрос предложений", "аукцион в электронной форме", "RFP", "RFQ", "RFI", "ТЗ", "обеспечение заявки"], "business": ["приглашаем принять участие в закупке", "приглашаем к участию в конкурсе", "просим направить коммерческое предложение в рамках запроса котировок", "объявлен тендер на поставку", "конкурсная документация во вложении", "закупочная процедура", "отбор поставщиков", "прошу подать заявку до", "проводим конкурентный отбор"], "patterns": ["«приглашаем к участию в» + «тендере / конкурсе / закупке»", "«срок подачи заявок до» + дата", "просим направить заявку", "«тендер на поставку» + товар", "«включены в список участников» (тендер сети, холдинга, госзаказчика)"]}'::jsonb, "anti_cues_ru" = '[{"code": "SALES_OFFER_REQUESTED", "text": "«пришлите КП на 200 штук к запуску»"}, {"code": "SALES_PRICE_REQUEST", "text": "«скиньте прайс, сравниваем поставщиков»"}, {"code": null, "text": "«по итогам закупки победителем признан»"}, {"code": null, "text": "рассылка «Подборка тендеров за неделю» от сервиса"}]'::jsonb, "example_ru" = '«Приглашаем вашу компанию принять участие в запросе котировок на поставку спецодежды для филиалов сети, срок подачи заявок — до 25.11 включительно, НМЦК 4,8 млн руб.»', "counter_example_ru" = '«Подготовьте, пожалуйста, коммерческое предложение на оснащение нового филиала» → это SALES_OFFER_REQUESTED: нет процедуры отбора и срока подачи заявок.', "note_ru" = 'Closed by: — (outcome of the tender is a separate event)
Date gate: — (the application deadline goes to `facts.deadlines`, owner = us)
Relevance window: until the application deadline («срок подачи заявок»); default when no deadline is given
Relations: — in v204. Agency pack: merges with `CONTRACT_RETENDER_ANNOUNCED` into one re-pitch card (Maslov §5.5).
Deal effect: per org rule. Usual: deal entry (deal type «тендер»). Agency: stage 1 «Новая возможность».', "updated_at" = now() WHERE "code" = 'SALES_TENDER_INVITATION';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Клиент просит образцы: одну или несколько единиц товара на пробу, тестовые образцы для технолога или инженера, пробники для закупочного комитета сети.', "boundary_ru" = 'Просьба провести демонстрацию или обучение персонала нашими силами — не этот код. Заказ небольшой партии с оплатой → ORDER_REQUESTED. Наша инициатива «давайте пришлём образцы» — не сигнал клиента. Образцы от нашего поставщика нам → нет сигнала.', "cues_prompt_ru" = ARRAY['пришлите образцы', 'образец на пробу', 'сэмплы', 'попробовать перед вводом', 'образцы для испытаний', 'пробник', 'для закупочного комитета', 'на тест технологу']::text[], "synonyms_ru" = '{"chat": ["закиньте пару штук на пробу", "скиньте сэмплы", "привезите попробовать", "можно по штуке на тест?", "технолог хочет проверить на нашей линии", "дайте пробник", "надо попробовать перед тем как брать"], "terms": ["образцы", "сэмплы", "пробник", "тестовая партия", "закупочный комитет", "сравнительный тест", "образцы на комитет"], "business": ["просим предоставить образцы", "прошу направить образцы следующих позиций", "для рассмотрения на закупочном комитете нужны образцы", "просим образцы для согласования ассортимента", "готовы рассмотреть позиции после испытания образцов", "сможете передать по одному образцу каждой позиции"], "patterns": ["пришлите / привезите / передайте + образцы / пробник + на пробу / на тест / на испытания"]}'::jsonb, "anti_cues_ru" = '[{"code": null, "text": "«проведите обучение для персонала»"}, {"code": "ORDER_REQUESTED", "text": "«возьмём на пробу 2 кор., посмотрим продажи»"}, {"code": null, "text": "«отправили вам образцы» (наше письмо)"}]'::jsonb, "example_ru" = '«Перед обновлением ассортимента хотим протестировать ваши герметики. Сможете передать по образцу на следующей неделе?»', "card_note_ru" = 'Пишите «Ответственный менеджер — согласовать и передать образцы клиенту»; укажите позиции и повод (ассортимент, комитет, испытания).', "note_ru" = 'Closed by: our reply on the topic (Open point 11)
Relations: `both` with `LISTING_OPPORTUNITY` (samples for an assortment review = one topic, two codes)
Deal effect: stage move: enter the selection stage (S2) on an open listing / new-location / tender deal; no deal entry', "updated_at" = now() WHERE "code" = 'SAMPLES_REQUESTED';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Победитель — наш конкурент → COMPETITOR_NEW_CLIENT. Заказ, размещённый у нас → SALES_BOOKING_RECEIVED / ORDER_REQUESTED. Своя кампания рекламодателя → SIGNAL_CAMPAIGN_PLANNED / SIGNAL_AD_ACTIVITY. Поставщик (не агентство) получил нового клиента или контракт на поставку → COMPETITOR_NEW_CLIENT, PARTNER_NEW_CLIENT или нет сигнала.', "updated_at" = now() WHERE "code" = 'SIGNAL_ACCOUNT_WIN';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Кампания объявлена, но ещё не стартовала → SIGNAL_CAMPAIGN_PLANNED. Годовой маркетинговый бюджет в отчётности → часть SIGNAL_RESULTS_*, не этот код. Конкурент у клиента → SIGNAL_COMPETITOR. Клиент просит у нас промоподдержку → PROMO_SUPPORT_REQUESTED. Наша собственная акция — нет сигнала.', "synonyms_ru" = '{"chat": ["у них сейчас реклама везде", "акция идёт до конца месяца", "ролик крутят по ТВ"], "news": ["сеть запустила рекламную кампанию с участием", "в эфире федеральных каналов вышел ролик бренда", "в магазинах сети действует акция «Второй товар за полцены» до 30 ноября", "реклама бренда появилась на билбордах", "сеть продолжает кампанию в Telegram-каналах"], "terms": ["«РК» (рекламная кампания)", "промо", "акция", "ролик", "наружка", "таргет", "посевы", "библиотека объявлений"], "business": ["у нас сейчас идёт акция на электроинструмент, до конца месяца", "кампания заканчивается 15-го, потом будем думать дальше"], "patterns": ["«[компания] запустила / ведёт [кампанию]», «акция действует до [даты]», «[ролик / реклама] вышел в [медиа]»"]}'::jsonb, "example_ru" = '«В магазинах «СтройМаркет» до 30 ноября действует акция на электроинструмент, реклама идёт в Telegram-каналах.»', "counter_example_ru" = '«С 1 декабря «СтройМаркет» запустит новогоднюю кампанию» → старт после даты материала, SIGNAL_CAMPAIGN_PLANNED.', "updated_at" = now() WHERE "code" = 'SIGNAL_AD_ACTIVITY';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Новая кампания того же агентства → SIGNAL_CAMPAIGN_PLANNED / SIGNAL_AD_ACTIVITY. Первое назначение агентства без тендера и без прежнего агентства → только SIGNAL_ACCOUNT_WIN. Агентство-конкурент потеряло рекламодателя, который не наш клиент → COMPETITOR_LOST_CLIENT. Смена агентства по трекингу или веб-аналитике → SIGNAL_TRACKING_VENDOR_CHANGE. Клиент меняет поставщика товаров (оборудования, сырья) — это не агентство: SIGNAL_COMPETITOR или нет сигнала.', "anti_cues_ru" = '[{"code": "SIGNAL_CAMPAIGN_PLANNED", "text": "«агентство «Альфа Медиа» запускает новую кампанию бренда»"}, {"code": "SIGNAL_ACCOUNT_WIN", "text": "«бренд впервые выбрал агентство»"}, {"code": "SIGNAL_TRACKING_VENDOR_CHANGE", "text": "«сменили подрядчика по Яндекс Метрике и тегам»"}, {"code": "SIGNAL_COMPETITOR", "text": "«будем брать комплектующие у другого поставщика»"}]'::jsonb, "updated_at" = now() WHERE "code" = 'SIGNAL_AGENCY_CHANGE';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания отмечает юбилей и в материале названа активность вокруг него: кампания, специальные продукты или издания, праздничное событие, акции, реклама. Например: вечер для партнёров, юбилейная скидка, юбилейная серия продукции.', "boundary_ru" = 'Юбилей просто упомянут, активность не названа → SIGNAL_ANNIVERSARY_PLAIN. Обычная сезонная акция без юбилея → SIGNAL_CAMPAIGN_PLANNED / SIGNAL_AD_ACTIVITY. Клиент просит нас поддержать юбилейную акцию → PROMO_SUPPORT_REQUESTED.', "cues_prompt_ru" = ARRAY['к юбилею запускает', 'юбилейная коллекция', 'юбилейная скидка', 'в честь 10-летия', 'праздничный вечер к юбилею', 'юбилейная акция', 'ограниченная серия к годовщине', 'отметит юбилей']::text[], "synonyms_ru" = '{"chat": ["у них юбилей, будет большая вечеринка", "к десятилетию делают акцию", "юбилейное предложение готовят"], "news": ["в честь 20-летия сеть запускает юбилейную акцию", "к юбилею завод проводит день открытых дверей для партнёров", "бренд выпустил юбилейную серию", "компания отметит 25-летие большим фестивалем", "юбилейная кампания стартует в декабре"], "terms": ["юбилей", "годовщина", "юбилейная серия", "лимитка", "день открытых дверей", "гала-вечер"], "business": ["в марте нам 10 лет, планируем вечер для клиентов и спецпредложение", "к юбилею хотим выпустить линейку с особыми позициями"], "patterns": ["«в честь [N-летия] [компания] [запускает / проводит] [что]», «к юбилею [что]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_ANNIVERSARY_PLAIN", "text": "«компании исполнилось 30 лет» (без активности)"}, {"code": "SIGNAL_CAMPAIGN_PLANNED", "text": "«новогодняя акция в магазинах»"}, {"code": "PROMO_SUPPORT_REQUESTED", "text": "«к юбилею просим поддержать нашу акцию скидкой»"}]'::jsonb, "example_ru" = '«К 15-летию компания «Техносфера» 20 марта проводит вечер для партнёров и запускает юбилейную серию оборудования.»', "counter_example_ru" = '«Компании «Техносфера» в марте исполняется 15 лет» → активность не названа, это SIGNAL_ANNIVERSARY_PLAIN.', "card_note_ru" = 'Это повод с датой и бюджетом: шаг — заранее узнать у контакта клиента, что планируется (вечер, акция, спецсерия), и потом предложить подборку; без поздравлений как действия.', "updated_at" = now() WHERE "code" = 'SIGNAL_ANNIVERSARY';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Материал только сообщает о юбилее компании или её подразделения; кампания, специальные продукты, событие или акция к юбилею не названы.', "boundary_ru" = 'Названа активность к юбилею (вечер, акция, серия) → SIGNAL_ANNIVERSARY. Дата основания в справке о компании без повода — нет сигнала. Юбилей сотрудника — нет сигнала.', "synonyms_ru" = '{"chat": ["им десятка", "у них юбилей", "пятнадцать лет уже"], "news": ["компании «Техносфера» исполнилось 15 лет", "сеть отмечает 20-летие", "компании четверть века", "логистическая компания празднует пятую годовщину"], "terms": ["юбилей", "годовщина", "N лет на рынке"], "business": ["в этом месяце нам 10 лет", "у нас юбилей, спасибо, что вы с нами"], "patterns": ["«[компании] исполнилось [N лет]», «[компания] отмечает [N-летие]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_ANNIVERSARY", "text": "«к юбилею готовим вечер для партнёров и спецпредложение»"}, {"code": null, "text": "«компания основана в 2006 году» (справка)"}, {"code": null, "text": "«у нашего главного инженера 10 лет в профессии»"}]'::jsonb, "example_ru" = '«В ноябре компании «Техносфера» исполняется 15 лет.»', "counter_example_ru" = '«В ноябре компании «Техносфера» исполняется 15 лет, к дате готовят день открытых дверей и юбилейную акцию» → активность названа, SIGNAL_ANNIVERSARY.', "updated_at" = now() WHERE "code" = 'SIGNAL_ANNIVERSARY_PLAIN';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания, её подразделение, продукт или сотрудник получает премию, награду, звание или место в рейтинге (например, отраслевые премии, рейтинги поставщиков, медали выставок).', "boundary_ru" = 'Награда конкуренту → COMPETITOR_AWARD, партнёру → PARTNER_AWARD. Награда у продукта, который мы закупаем, в письме поставщика → нет сигнала (или SUPPLIER_PRICE_CHANGE, если пришёл новый прайс). Компания сама вручает премию или спонсирует её → SIGNAL_SPONSORING. Наша собственная награда — нет сигнала.', "cues_prompt_ru" = ARRAY['получил премию', 'вошёл в рейтинг', 'стал лауреатом', 'лучший поставщик года', 'лучший продукт года', 'золотая медаль', 'победитель конкурса', 'диплом выставки']::text[], "synonyms_ru" = '{"chat": ["им медаль дали", "попали в топ", "взяли премию"], "news": ["компания вошла в топ-50 отраслевого рейтинга", "дилер получил премию «Лучший дилер года»", "продукт компании получил золотую медаль выставки", "инженер компании стал победителем национального конкурса профмастерства", "сеть признана лучшим ретейлером года"], "terms": ["премия", "рейтинг", "выставка", "лауреат", "номинация", "медаль", "конкурс профмастерства"], "business": ["нас включили в рейтинг, спасибо за помощь с проектом", "наш инженер выиграл конкурс"], "patterns": ["«[компания] получила [премию / награду]», «вошла в [рейтинг]», «стала лауреатом [премии]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "COMPETITOR_AWARD", "text": "««ПромСнаб» стал поставщиком года»"}, {"code": "SIGNAL_SPONSORING", "text": "«компания учредила премию для молодых инженеров»"}, {"code": null, "text": "«продукт получил медаль выставки, новый прайс во вложении»"}]'::jsonb, "example_ru" = '«Логистическая компания «ТрансЛайн» получила премию «Лучший логистический оператор года» в номинации «Москва».»', "counter_example_ru" = '««ПромСнаб» признан лучшим поставщиком года» → награда конкуренту, COMPETITOR_AWARD.', "updated_at" = now() WHERE "code" = 'SIGNAL_AWARD';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания объявляет или планирует кампанию, промоакцию, запуск с продвижением или медиаплан, которые ещё не начались: дата старта позже даты материала, кампания в производстве, тендер на кампанию. Бюджет ещё не размещён. Для розницы и производителей — сезонная акция, новогодняя или праздничная промо, фестиваль в сети.', "boundary_ru" = 'Кампания уже идёт или заканчивается → SIGNAL_AD_ACTIVITY. Только новый продукт без кампании → SIGNAL_PRODUCT_NEWS. Клиент просит нас поддержать акцию (бонус, POS, промо) → PROMO_SUPPORT_REQUESTED. Конкурент у клиента → SIGNAL_COMPETITOR.', "synonyms_ru" = '{"chat": ["к Новому году готовят акцию", "скоро запуск кампании", "съёмки ролика на следующей неделе"], "news": ["сеть с 1 декабря запустит новогоднюю кампанию", "бренд готовит масштабную кампанию к запуску", "ретейлер объявил тендер на проведение весенней кампании", "ролик уже снимают, выход в феврале"], "terms": ["РК", "медиаплан", "промо", "запуск", "старт", "сезонная акция", "ко дню"], "business": ["в декабре у нас будет большая акция на бытовую технику, планируем объёмы", "готовим весенний садовый фестиваль во всех магазинах, старт 1 апреля", "к 8 Марта делаем промо"], "patterns": ["«[компания] запустит [кампанию] с [даты]», «готовим [акцию] к [поводу]», «старт [кампании] запланирован на [дату]»"]}'::jsonb, "example_ru" = '«С 1 декабря во всех 40 магазинах «СтройМаркет» стартует новогодняя акция на электроинструмент и подарочные наборы.»', "counter_example_ru" = '«В магазинах «СтройМаркет» сейчас идёт акция на электроинструмент, последняя неделя» → кампания уже идёт, SIGNAL_AD_ACTIVITY.', "updated_at" = now() WHERE "code" = 'SIGNAL_CAMPAIGN_PLANNED';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания переносит бюджет между каналами рекламы, маркетинга или сбыта при примерно той же общей сумме: из печати в digital, из ТВ в соцсети; для поставщика — из офлайн-розницы в онлайн-продажи или из розницы в прямые B2B-продажи.', "example_ru" = '«В 2027 году «СтройМаркет» переносит треть рекламного бюджета из наружной рекламы в Telegram-каналы и блогеров при прежнем общем объёме.»', "counter_example_ru" = '«В 2027 году «СтройМаркет» удвоит рекламный бюджет» → меняется общая сумма, это SIGNAL_STRATEGY_ANNOUNCEMENT.', "updated_at" = now() WHERE "code" = 'SIGNAL_CHANNEL_SHIFT';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'У нашего клиента появляется конкурент: клиент говорит, что работает или начинает работать с другим поставщиком, рассматривает его продукцию, конкурент проводит у клиента демонстрацию или презентацию. Без связи с конкретным клиентом это не сигнал.', "boundary_ru" = 'Жалоба на цену со ссылкой на более дешёвое предложение → COMPLAINT_PRICE. Клиент выводит наши позиции → DELISTING_RISK. Новость о конкуренте без связи с нашим клиентом → блок L (COMPETITOR_*). Отказ от нашего предложения с выбором другого поставщика → SALES_OFFER_DECLINED (если отказ явный, этот код можно поставить вторым).', "cues_prompt_ru" = ARRAY['работаем с другим поставщиком', 'нам предложил другой поставщик', 'взяли у другого поставщика', 'рассматриваем предложение конкурента', 'у нас была презентация от', 'перешли на другого подрядчика', 'часть позиций берём у', 'к нам приходил представитель']::text[], "synonyms_ru" = '{"chat": ["нам «ПромСнаб» тоже предлагал", "крепёж теперь берём у других", "к нам ихний торговый приходил", "конкуренты зашли с демонстрацией"], "terms": ["другой поставщик", "подрядчик", "альтернативное предложение", "торговый представитель", "демонстрация", "портфолио"], "business": ["по кабельной продукции мы теперь работаем с другим поставщиком", "нам поступило предложение от другого поставщика, рассматриваем", "часть позиций переводим к другому подрядчику", "на следующей неделе у нас презентация от «ПромСнаба»", "сравниваем ваше портфолио с альтернативным"], "patterns": ["«работаем / начали работать с [другим поставщиком]», «[конкурент] предложил нам [позиции / условия]», «переводим [позиции] к [конкуренту]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "COMPLAINT_PRICE", "text": "«у другого поставщика на 15 % дешевле, дайте скидку»"}, {"code": "DELISTING_RISK", "text": "«убираем ваши позиции из ассортимента»"}, {"code": "COMPETITOR_EXPANSION", "text": "««ПромСнаб» открыл склад в Казани» (без связи с клиентом)"}, {"code": "SALES_OFFER_DECLINED", "text": "«спасибо, выбрали другого поставщика»"}]'::jsonb, "example_ru" = '«Кабельную продукцию с января будем брать у «ПромСнаба», они дали лучшую логистику.»', "counter_example_ru" = '««ПромСнаб» стал официальным дилером нового бренда» → новость о конкуренте без связи с нашим клиентом, это блок L.', "updated_at" = now() WHERE "code" = 'SIGNAL_COMPETITOR';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Меняется руководство вне маркетинга: генеральный директор, финансовый, операционный, коммерческий, технический директор, директор по персоналу, руководитель продаж, управляющий направлением (например, розничным), члены совета директоров или правления.', "boundary_ru" = 'Новый руководитель маркетинга, бренда, коммуникаций → SIGNAL_NEW_MARKETING_LEAD. Новый закупщик или категорийный менеджер, который пишет нам сам → CONTACT_NEW_DECISION_MAKER. Смена произошла больше 6 месяцев назад — нет сигнала. Смена директора у нашего поставщика → PARTNER_PERSONNEL или нет сигнала; у конкурента → COMPETITOR_PERSONNEL.', "synonyms_ru" = '{"chat": ["у них гендир поменялся", "новый коммерческий пришёл", "финдиректора сменили, теперь всё через него"], "news": ["генеральным директором компании назначен", "в ЕГРЮЛ внесены сведения о новом руководителе", "покинул пост генерального директора", "новым коммерческим директором стал", "совет директоров избрал председателем", "операционным директором группы компаний назначен"], "terms": ["гендир", "ГД", "CEO", "CFO", "COO", "коммерческий директор", "совет директоров", "ЕГРЮЛ"], "business": ["сообщаем о смене генерального директора, документы во вложении", "с 01.12 договоры подписывает новый генеральный директор", "доверенность выдана новым руководителем"], "patterns": ["«[ФИО] назначен(а) [должность]», «[ФИО] покинул(а) пост [должность]», «смена [генерального директора] в [компании]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_NEW_MARKETING_LEAD", "text": "«новый директор по маркетингу»"}, {"code": "CONTACT_NEW_DECISION_MAKER", "text": "«я новый закупщик»"}, {"code": null, "text": "«генеральный директор с 2022 года»"}, {"code": "COMPETITOR_PERSONNEL", "text": "«у «ПромСнаба» новый гендир»"}]'::jsonb, "updated_at" = now() WHERE "code" = 'SIGNAL_C_LEVEL_CHANGE';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания закрывает свои точки, магазины, склады, филиалы или производство, уходит из региона или сокращает персонал. Речь о действующей компании, которая сжимает бизнес.', "boundary_ru" = 'Процедура банкротства или ликвидации → SIGNAL_INSOLVENCY. Клиент убирает наши позиции из ассортимента → DELISTING_RISK. Временное закрытие на ремонт, санитарный день или сезонная пауза с датой открытия — нет сигнала. Закрытие за рубежом, вне регионов из профиля организации, — нет сигнала. Перевод точки по новому адресу → SIGNAL_EXPANSION только если открывается новая площадка; иначе нет сигнала.', "cues_prompt_ru" = ARRAY['закрывает филиалы', 'закрытие точки', 'сокращение штата', 'оптимизация персонала', 'уходит из региона', 'сворачивает сеть', 'закрываемся с 1-го числа', 'массовые увольнения']::text[], "synonyms_ru" = '{"chat": ["мы закрываемся", "склад закрываем, аренду не потянули", "точку на Белорусской закрыли", "у них всех закупщиков сократили", "сворачиваются потихоньку"], "news": ["сеть закроет 15 магазинов до конца года", "группа компаний сократит 300 сотрудников", "компания уходит из регионов", "оптимизирует розничную сеть", "закрыла завод в Калужской области", "сокращает штат на 10 %"], "terms": ["оптимизация", "реструктуризация сети", "«закрытие ТТ» (торговой точки)", "сокращение ФОТ"], "business": ["с 01.12 филиал на Тверской прекращает работу", "мы закрываем два магазина из пяти", "в связи с оптимизацией сети точка закрывается", "просим не планировать поставки на адрес Покровка, 12 после 30.11", "у нас сокращение, отдел закупок урезали вдвое", "прекращаем деятельность в Санкт-Петербурге"], "patterns": ["«[компания] закрывает / закроет [N точек]», «прекращает работу [точка / регион]», «сокращает [N сотрудников / %]»"]}'::jsonb, "anti_cues_ru" = '[{"code": null, "text": "«закрыты на ремонт до 15.01»"}, {"code": "SIGNAL_INSOLVENCY", "text": "«вводим процедуру банкротства»"}, {"code": "DELISTING_RISK", "text": "«убираем вашу продукцию из ассортимента»"}, {"code": "SIGNAL_EXPANSION", "text": "«переезжаем в новое помещение, откроемся 01.02»"}, {"code": null, "text": "«закрываем магазины в Казахстане»"}]'::jsonb, "example_ru" = '«Коллеги, с 1 декабря закрываем склад на Покровке, поставки туда больше не планируйте.»', "counter_example_ru" = '«Склад закрыт на инвентаризацию, принять поставку не сможем, перенесите на завтра» → это не сокращение бизнеса.', "updated_at" = now() WHERE "code" = 'SIGNAL_DOWNSIZING';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Событие ещё впереди → SIGNAL_EVENT_UPCOMING. Компания выступает спонсором → SIGNAL_SPONSORING. Наше собственное участие — нет сигнала. Встреча или презентация у клиента с нами → блок F.', "synonyms_ru" = '{"chat": ["они на выставке стояли", "видел их на фестивале", "были на форуме, выступали"], "news": ["компания представила новинки на выставке", "ИТ-интегратор принял участие в технологическом фестивале", "генеральный директор выступил на отраслевом форуме", "по итогам выставки сеть подписала соглашения", "производитель вошёл в число участников выставки"], "terms": ["выставка", "стенд", "форум", "фестиваль", "конференция", "спикер", "экспонент"], "business": ["мы только вернулись с выставки, было много контактов", "на прошлой неделе были на форуме ретейла"], "patterns": ["«[компания] представила [что] на [событии]», «приняла участие в [событии]», «по итогам [события]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_EVENT_UPCOMING", "text": "«в феврале будем на выставке, приходите»"}, {"code": "SIGNAL_SPONSORING", "text": "«выступили генеральным спонсором фестиваля»"}, {"code": null, "text": "«мы (наша компания) провели презентацию»"}]'::jsonb, "example_ru" = '«Сеть «СтройМаркет» представила на прошедшей выставке свою новую марку инструмента и подписала два соглашения с поставщиками.»', "counter_example_ru" = '«Сеть «СтройМаркет» примет участие в выставке в феврале 2027 года» → событие впереди, это SIGNAL_EVENT_UPCOMING.', "updated_at" = now() WHERE "code" = 'SIGNAL_EVENT';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Событие прошло или дата не указана → SIGNAL_EVENT. Компания — спонсор → SIGNAL_SPONSORING. Клиент приглашает нас на встречу или презентацию к себе → блок F (MEETING_*). Наше участие — нет сигнала.', "synonyms_ru" = '{"chat": ["они в феврале на выставке будут", "на выставке у них свой стенд будет", "едут на форум"], "news": ["сеть представит новинки на выставке в феврале", "основатель ИТ-интегратора выступит на технологическом форуме", "производитель примет участие в строительной выставке 12–14 декабря", "компания объявила об участии в отраслевой выставке"], "terms": ["выставка", "стенд", "экспонент", "спикер", "форум", "фестиваль", "деловая программа"], "business": ["в феврале будем на выставке, стенд B-12, заходите", "я выступаю на форуме ретейла 3 декабря, увидимся там?"], "patterns": ["«[компания] примет участие в [событии] [дата]», «приглашаем на стенд [номер]», «[руководитель] выступит на [событии]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_EVENT", "text": "«по итогам выставки подписали соглашения»"}, {"code": "SIGNAL_SPONSORING", "text": "«станем генеральным спонсором фестиваля»"}, {"code": null, "text": "«приезжайте к нам в офис на презентацию в четверг» (приглашение к себе — блок F)"}]'::jsonb, "example_ru" = '«Группа компаний «Техносфера» представит новую линейку оборудования на отраслевой выставке 12–14 декабря в Москве.»', "counter_example_ru" = '«Группа компаний «Техносфера» представила новую линейку оборудования на прошедшей выставке» → событие прошло, SIGNAL_EVENT.', "updated_at" = now() WHERE "code" = 'SIGNAL_EVENT_UPCOMING';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания открывает новую точку, магазин, офис, филиал, склад для клиентов или выходит на новый рынок в регионах из профиля организации, либо набирает персонал под новую площадку. Источник — новости, реестры или упоминание третьей стороной.', "boundary_ru" = 'Клиент сам пишет нам, что открывает новую точку → NEW_VENUE_OPENING; этот код тогда не ставится. Расширение за рубежом или вне регионов профиля — нет сигнала. Общие слова о росте без названной площадки («планируем расти») → SIGNAL_STRATEGY_CONTEXT. Новый склад или цех только для своей работы → SIGNAL_OPERATIONS_INVESTMENT. Слияние или покупка сети → SIGNAL_MERGER.', "cues_prompt_ru" = ARRAY['открытие нового офиса', 'открывает магазин', 'новая точка', 'новый филиал', 'выходит в регион', 'открылся по адресу', 'расширяет сеть', 'набирает персонал в новый']::text[], "synonyms_ru" = '{"chat": ["они ещё точку открывают", "новый магазин у них на Покровке", "заходят в Питер", "набирают команду на открытие"], "news": ["группа компаний откроет пять филиалов в 2027 году", "сеть вышла в Санкт-Петербург", "в ТЦ открылся новый магазин сети", "на Патриарших открылся шоурум компании", "компания открыла филиал в Казани", "сеть расширилась до 30 магазинов", "открытие запланировано на март"], "terms": ["«новая ТТ» (торговая точка)", "открытие", "софт-опенинг", "гранд-опенинг", "франшиза", "выход в регион"], "patterns": ["«[компания] открывает / откроет [точку] в [месте]», «выходит на рынок [региона]», «расширяет сеть до [N]»"], "business_third_party": ["слышали, что «Техносфера» открывает второй сервисный центр на Белорусской", "у «СтройМаркета» новый магазин в Химках"]}'::jsonb, "anti_cues_ru" = '[{"code": "NEW_VENUE_OPENING", "text": "«мы открываем второй магазин, нужна поставка» (пишет сам клиент)"}, {"code": null, "text": "«открываем магазины в Казахстане»"}, {"code": "SIGNAL_STRATEGY_CONTEXT", "text": "«хотим расти в следующем году»"}, {"code": "SIGNAL_OPERATIONS_INVESTMENT", "text": "«построили новый распределительный центр»"}]'::jsonb, "example_ru" = '«Компания «Техносфера» в феврале откроет сервисный центр в Казани.»', "counter_example_ru" = '«Компания «Техносфера» открывает филиал в Дубае» → площадка вне регионов профиля, сигнала нет.', "card_note_ru" = 'Назовите площадку и дату открытия; шаг — узнать у закупщика или управляющего клиента, кто формирует закупки для новой точки и когда, и предложить подборку после этого.', "note_ru" = 'Date gate: — (place check: only regions of the org profile)
Deal effect: per org rule; usual: none (the code `NEW_VENUE_OPENING` is the deal entry when the client confirms it)', "updated_at" = now() WHERE "code" = 'SIGNAL_EXPANSION';
--> statement-breakpoint
UPDATE "signal_category" SET "example_ru" = '«Сеть магазинов «СтройМаркет» привлекла 250 млн ₽ от частного фонда за 25 % на открытие новых магазинов.»', "counter_example_ru" = '«Холдинг «Гастроном Плюс» выкупил 75 % «СтройМаркета»» → смена контроля, это SIGNAL_MERGER.', "updated_at" = now() WHERE "code" = 'SIGNAL_FUNDING';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Новое регулирование или отраслевое изменение с понятным последствием для клиентов: например, изменение налогов, сборов и пошлин на импорт, требований к маркировке и сертификации, лицензирования, ограничений продаж; общее изменение спроса в отрасли.', "boundary_ru" = 'Событие одной компании → другой H-код. Конкретная проблема одного клиента с документами, маркировкой или поставкой — не этот код. Изменение цен нашего поставщика → SUPPLIER_PRICE_CHANGE. Общая аналитика без последствия для клиентов — нет сигнала.', "cues_prompt_ru" = ARRAY['с 1 января вырастут ставки', 'новые требования к сертификации', 'повышение ввозных пошлин', 'изменения в правилах закупок', 'новые требования к маркировке', 'закон вступает в силу', 'ограничение продаж', 'рынок сократился']::text[], "synonyms_ru" = '{"chat": ["пошлины опять подняли", "пошлины на европейское оборудование задрали", "в маркировке опять всё поменяли", "требования к сертификации ужесточили"], "news": ["правительство ввело новые требования к сертификации строительных материалов", "с 2027 года утилизационный сбор на спецтехнику вырастет", "правительство повысило пошлины на оборудование из недружественных стран", "Минпромторг расширяет обязательную маркировку на новые товарные группы", "регион ввёл ограничения на строительство в центре города", "рынок импортной электроники за 9 месяцев сократился на 12 %"], "terms": ["пошлина", "утильсбор", "сертификация", "ГОСТ", "техрегламент", "Честный знак", "маркировка", "44-ФЗ", "223-ФЗ"], "business": ["в связи с ростом пошлин с 01.01 цены на импорт изменятся", "у нас в области ограничили стройку, закупки сократим"], "patterns": ["«с [даты] [изменится / вводится] [норма]», «[ведомство] повысило / утвердило [что]», «рынок [категории] [вырос / сократился] на [N %]»"]}'::jsonb, "anti_cues_ru" = '[{"code": null, "text": "«у нас одна партия третий день стоит на таможне» (проблема одного клиента)"}, {"code": "SUPPLIER_PRICE_CHANGE", "text": "«производитель поднимает цены с 01.12»"}, {"code": "SIGNAL_DOWNSIZING", "text": "«сеть закрывает магазины из-за ограничений»"}]'::jsonb, "example_ru" = '«С 1 января 2027 года утилизационный сбор на спецтехнику повышается, сообщил Минпромторг.»', "counter_example_ru" = '«У нас партия третий день стоит на таможне, не можем принять» → проблема одного клиента, не отраслевая тенденция.', "updated_at" = now() WHERE "code" = 'SIGNAL_INDUSTRY_TREND';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Негативная публикация без признаков неплатёжеспособности → SIGNAL_NEGATIVE_PRESS. Просрочка одного счёта или обещание оплатить позже → INVOICE_OVERDUE / PAYMENT_PROMISE. Просьба об отсрочке или рассрочке → PAYMENT_TERMS_REQUEST. Новость о том, что покупатель выкупает или спасает бизнес банкрота → SIGNAL_MERGER для покупателя, банкротство — только контекст. Реорганизация в форме присоединения или слияния → SIGNAL_MERGER. Закрытие отдельных точек без признаков неплатёжеспособности → SIGNAL_DOWNSIZING. Банкротство компании, которая не наш клиент и не связана с ним, — нет сигнала.', "anti_cues_ru" = '[{"code": "SIGNAL_MERGER", "text": "«группа выкупила заводы у конкурсного управляющего и сохранит их»"}, {"code": "INVOICE_OVERDUE", "text": "«оплатим на следующей неделе, задержка с платежом»"}, {"code": "PAYMENT_TERMS_REQUEST", "text": "«просим отсрочку 60 дней»"}, {"code": "SIGNAL_DOWNSIZING", "text": "«закрываем две точки в ТЦ»"}, {"code": "SIGNAL_MERGER", "text": "«реорганизация в форме присоединения к АО»"}, {"code": null, "text": "«в ЕГРЮЛ запись о недостоверности адреса»"}, {"code": "SIGNAL_RESULTS_NEGATIVE", "text": "«выручка упала на 20 %»"}]'::jsonb, "counter_example_ru" = '«Холдинг «Гастроном Плюс» выкупил бизнес «Северного ветра» у конкурсного управляющего и сохранит все магазины» → это SIGNAL_MERGER для покупателя; банкротство здесь контекст.', "updated_at" = now() WHERE "code" = 'SIGNAL_INSOLVENCY';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания ищет человека на роль, важную для нас: маркетинг, бренд, закупки, категорийный менеджмент; для поставщика — закупщик, руководитель закупок, категорийный менеджер, главный инженер.', "boundary_ru" = 'Вакансии без связи с нашей областью (курьер, водитель, бухгалтер) — нет сигнала. Набор команды под открытие новой точки → SIGNAL_EXPANSION. Человек уже назначен → SIGNAL_NEW_MARKETING_LEAD / SIGNAL_C_LEVEL_CHANGE / CONTACT_NEW_DECISION_MAKER. Вакансия у нас самих — нет сигнала.', "cues_prompt_ru" = ARRAY['ищем главного инженера', 'вакансия закупщика', 'требуется бренд-менеджер', 'открыта вакансия категорийного менеджера', 'ищем руководителя направления', 'в команду маркетинга требуется', 'вакансия на hh.ru', 'нанимаем руководителя закупок']::text[], "synonyms_ru" = '{"chat": ["они категорийщика ищут", "вакансия висит на хэдхантере", "закупщика нет, ищут"], "news": ["сеть ищет категорийного менеджера по электротоварам", "производитель открыл вакансию главного инженера", "требуется менеджер по закупкам комплектующих", "в отдел маркетинга требуется бренд-менеджер"], "terms": ["hh.ru", "вакансия", "«КМ» (категорийный менеджер)", "руководитель закупок", "главный инженер", "байер"], "business": ["наш закупщик ушёл, сейчас ищем нового", "пока ищем закупщика, заказы делает управляющий"], "patterns": ["«ищем / требуется [роль]», «открыта вакансия [роль]», «в команду [отдела] нужен [роль]»"]}'::jsonb, "anti_cues_ru" = '[{"code": null, "text": "«ищем водителей и грузчиков»"}, {"code": "SIGNAL_EXPANSION", "text": "«набираем команду на открытие нового магазина»"}, {"code": "CONTACT_NEW_DECISION_MAKER", "text": "«я новый закупщик, давайте знакомиться»"}, {"code": "CONTACT_LEAVING", "text": "«я ухожу из компании»"}]'::jsonb, "example_ru" = '«Группа компаний «Техносфера» ищет руководителя закупок с опытом работы с поставщиками комплектующих для четырёх заводов.»', "counter_example_ru" = '«Группа компаний «Техносфера» набирает грузчиков и водителей на сезон» → роли вне нашей области.', "updated_at" = now() WHERE "code" = 'SIGNAL_JOB_POSTING';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["их купили", "теперь они под «Гастроном Плюс»", "собственник поменялся", "их поглотили"], "news": ["группа приобрела сеть магазинов", "выкупила 100 % долей", "получила контроль над", "ФАС одобрила ходатайство о покупке", "компании объявили о слиянии", "реорганизация в форме присоединения", "новым владельцем стал", "выкупила бренд у конкурсного управляющего", "сделка по спасению сети закрыта"], "terms": ["M&A", "ФАС", "контрольный пакет", "мажоритарий", "присоединение", "правопреемник", "новое юрлицо"], "business": ["сообщаем, что с 01.12 общество вошло в состав группы «Гастроном Плюс»", "у нас сменился собственник", "в связи с реорганизацией в форме присоединения просим перезаключить договор", "все договоры переходят к новому юрлицу"], "patterns": ["«[покупатель] приобрёл / выкупил [компанию / долю N %]», «[компания] вошла в состав [группы]», «сделка по покупке [компании] закрыта»"]}'::jsonb, "example_ru" = '«Холдинг «Гастроном Плюс» закрыл сделку по покупке 100 % сети магазинов «СтройМаркет».»', "counter_example_ru" = '«Холдинг «Гастроном Плюс» и «СтройМаркет» запускают совместную программу лояльности» → это партнёрство, контроль не меняется.', "updated_at" = now() WHERE "code" = 'SIGNAL_MERGER';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["у них жесть в отзывах", "их сейчас в телеге полощут", "хайп из-за отравления", "Роспотреб к ним пришёл"], "news": ["застройщик оказался в центре скандала", "Роспотребнадзор приостановил работу предприятия", "сеть обвинили в продаже контрафакта", "покупатели объявили бойкот", "бренд отзывает партию продукции", "в сети разгорелся скандал после поста покупателя", "прокуратура начала проверку"], "terms": ["Роспотребнадзор", "Ростехнадзор", "предписание", "отзыв продукции", "контрафакт", "фальсификат", "административное дело"], "business": ["у нас сейчас непростая ситуация в соцсетях", "по сети пошла волна отзывов после отравления", "мы получили предписание Роспотребнадзора", "партия отозвана из продажи по решению надзора"], "patterns": ["«[компания] оказалась в центре [скандала]», «[надзор] выявил нарушения у [компании]», «[компания] отзывает [продукцию]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_INSOLVENCY", "text": "«введено конкурсное производство»"}, {"code": "SIGNAL_RESULTS_NEGATIVE", "text": "«убыток за 9 месяцев вырос на 30 %»"}, {"code": "COMPLAINT_QUALITY", "text": "«покупатель пожаловался на брак в вашей партии»"}, {"code": "COMPETITOR_NEGATIVE_PRESS", "text": "«конкурент попал в скандал»"}]'::jsonb, "example_ru" = '«Ростехнадзор приостановил работу цеха компании «Техносфера» на 30 суток после проверки.»', "counter_example_ru" = '«Компания «Техносфера» закрывает цех, аренду не продлили» → это SIGNAL_DOWNSIZING, не репутационный кризис.', "updated_at" = now() WHERE "code" = 'SIGNAL_NEGATIVE_PRESS';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Зарегистрирована новая компания или открыт новый бизнес, у которого ещё нет партнёров. Для поставщика важны новые компании из отраслей его клиентов — магазины, производства, сервисные и строительные компании, которые ещё не выбрали поставщиков.', "cues_prompt_ru" = ARRAY['зарегистрирована новая компания', 'открылась новая компания', 'новый проект предпринимателя', 'получила лицензию на деятельность', 'создано ООО', 'стартап', 'новый бизнес от команды', 'запуск нового бизнеса']::text[], "synonyms_ru" = '{"chat": ["ребята новую мастерскую открывают", "у бывшего директора свой проект стартует", "новая контора, только зарегались"], "news": ["в ЕГРЮЛ зарегистрировано ООО с видом деятельности «строительство жилых и нежилых зданий»", "предприниматель открывает новый проект", "команда интегратора запускает собственную компанию", "новой компании выдан допуск СРО на строительные работы", "на рынок вышел новый игрок"], "terms": ["ЕГРЮЛ", "ОКВЭД", "лицензия", "допуск СРО", "новое ООО", "ИП"], "business": ["мы новая компания, открываемся в марте, ищем поставщика оборудования", "знакомые открывают автосервис, им нужен поставщик"], "patterns": ["«зарегистрировано [ООО] с [видом деятельности]», «[команда / предприниматель] открывает новый проект [название]», «получена лицензия [на вид деятельности]»"]}'::jsonb, "example_ru" = '«Бывший технический директор «Техносферы» открывает собственную инжиниринговую компанию «Вектор», запуск в марте.»', "counter_example_ru" = '«Сеть «СтройМаркет» открыла новый магазин в Химках» → это новая точка действующей сети, SIGNAL_EXPANSION.', "updated_at" = now() WHERE "code" = 'SIGNAL_NEW_COMPANY';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'В компании новый руководитель маркетинга, бренда или коммуникаций — человек, который решает о бюджете в нашей области. Для поставщика к этой роли относится также руководитель категории или направления, если в тексте он решает о закупках.', "cues_prompt_ru" = ARRAY['назначен директором по маркетингу', 'новый CMO', 'возглавил маркетинг', 'новый бренд-директор', 'назначена руководителем направления коммуникаций', 'пришёл новый маркетолог', 'новый руководитель категории', 'перешёл на позицию директора по маркетингу']::text[], "synonyms_ru" = '{"chat": ["у них новый маркетолог", "маркетинг теперь ведёт новая девушка", "пришёл новый CMO, всё пересматривает", "поменялся руководитель категории"], "news": ["директором по маркетингу компании назначен", "новым CMO сети стала", "возглавила департамент маркетинга и коммуникаций", "на позицию бренд-директора пришёл", "группа компаний назначила нового директора по маркетингу", "руководителем категории в сети стал"], "terms": ["CMO", "бренд-директор", "директор по маркетингу", "руководитель PR", "руководитель категории", "бренд-менеджер"], "business": ["сообщаем, что с 01.11 директором по маркетингу назначена Анна Смирнова", "теперь маркетинг курирует новый руководитель", "по вопросам продвижения обращайтесь к новому бренд-менеджеру"], "patterns": ["«[ФИО] назначен(а) [директором по маркетингу]», «на должность [CMO] пришёл / пришла», «[ФИО] возглавил(а) [маркетинг]»"]}'::jsonb, "example_ru" = '«Директором по маркетингу группы компаний «Техносфера» назначена Анна Смирнова, ранее работавшая в сети «СтройМаркет».»', "counter_example_ru" = '«Анна Смирнова, директор по маркетингу «Техносферы» с 2023 года, рассказала о планах на сезон» → назначение старое, сигнала нет.', "updated_at" = now() WHERE "code" = 'SIGNAL_NEW_MARKETING_LEAD';
--> statement-breakpoint
UPDATE "signal_category" SET "example_ru" = '«Сеть «СтройМаркет» впервые вошла в топ-50 рекламодателей категории «Строительство и ремонт» (12 млн ₽ за октябрь 2026).»', "counter_example_ru" = '«Наш клиент «Гастроном Плюс» поднялся с 40-го на 20-е место» → клиент уже наш, это SIGNAL_SPEND_UP.', "updated_at" = now() WHERE "code" = 'SIGNAL_NEW_TOP_SPENDER';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["склад новый строят", "машины обновили", "кассы меняют"], "news": ["сеть построит распределительный центр в Подмосковье", "компания обновила автопарк рефрижераторов", "группа компаний внедряет новую ERP-систему", "ретейлер инвестирует 2 млрд ₽ в логистику", "поставщик оборудования получил крупный заказ от сети"], "terms": ["«РЦ» (распределительный центр)", "автопарк", "ERP", "WMS", "капекс", "модернизация"], "business": ["мы переезжаем на новый склад, с декабря новый адрес приёмки", "ставим новую систему учёта, возможны задержки в подтверждении заказов"], "patterns": ["«[компания] инвестирует [сумму] в [что]», «запускает / построит [объект]», «получила заказ на поставку [чего] для [компании]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_PRODUCT_NEWS", "text": "«запускаем собственную марку инструмента»"}, {"code": "SIGNAL_EXPANSION", "text": "«открываем новый магазин»"}, {"code": "ORDER_REQUESTED", "text": "«закажите нам 50 коробок»"}]'::jsonb, "updated_at" = now() WHERE "code" = 'SIGNAL_OPERATIONS_INVESTMENT';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["у них колаба с производителем мебели", "вместе с доставкой что-то запускают", "зашли в партнёрство"], "news": ["сеть и сервис доставки подписали соглашение о стратегическом партнёрстве", "производитель и дизайн-студия запускают коллаборацию", "компании создали совместное предприятие", "бренд выходит в регионы по франшизе через партнёра", "банк и сеть магазинов запустили совместную программу лояльности"], "terms": ["коллаборация", "колаба", "СП", "соглашение о сотрудничестве", "франшиза", "кобрендинг"], "business": ["мы начинаем проект с сервисом доставки, объёмы вырастут", "делаем совместный вебинар с производителем"], "patterns": ["«[компания] и [компания] подписали [соглашение]», «запускают совместный [проект / продукт]», «стали партнёрами в [области]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_MERGER", "text": "«холдинг купил 60 % компании»"}, {"code": "SIGNAL_COMPETITOR", "text": "«комплектующие теперь берём у «ПромСнаба»»"}, {"code": "SIGNAL_SPONSORING", "text": "«стали генеральным спонсором фестиваля»"}]'::jsonb, "example_ru" = '«Сеть «СтройМаркет» и сервис доставки «Быстро» подписали соглашение: с декабря товары сети будут доступны в приложении.»', "updated_at" = now() WHERE "code" = 'SIGNAL_PARTNERSHIP';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Клиент убирает НАШИ позиции из ассортимента → DELISTING_RISK. Мы выводим свою позицию → INTERNAL_PRODUCT_STATUS_UPDATE. Поставщик прекращает выпуск товара, который мы закупаем → SUPPLIER_DELIVERY_DELAY («больше не производится»). Отзыв партии по решению надзора → SIGNAL_NEGATIVE_PRESS. Закрытие точки → SIGNAL_DOWNSIZING.', "synonyms_ru" = '{"chat": ["они эту линейку закрыли", "монтаж больше не делают", "бренд свернули"], "news": ["компания прекращает выпуск бренда", "сеть закрывает направление кулинарии", "бренд уходит из категории бытовой техники", "ретейлер выводит из продажи линейку СТМ", "сеть отказывается от формата магазинов у дома"], "terms": ["вывод из линейки", "снятие с производства", "делистинг", "закрытие направления", "СТМ"], "business": ["мы закрываем направление сервисного обслуживания с января", "сеть пунктов выдачи сворачиваем", "формат доставки прекращаем"], "patterns": ["«[компания] прекращает [выпуск / продажу] [продукта]», «закрывает направление [что]», «уходит из [категории]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "DELISTING_RISK", "text": "«убираем вашу продукцию из ассортимента»"}, {"code": "SUPPLIER_DELIVERY_DELAY", "text": "«производитель больше не выпускает эту модель»"}, {"code": "SIGNAL_NEGATIVE_PRESS", "text": "«партию отозвали по предписанию»"}, {"code": "SIGNAL_DOWNSIZING", "text": "«закрываем филиал»"}]'::jsonb, "example_ru" = '«Компания «Техносфера» с 1 января закрывает направление выездного сервисного обслуживания.»', "counter_example_ru" = '«Мы больше не берём у вас эту модель насосов, выводим из ассортимента» → это наши позиции у клиента, DELISTING_RISK.', "updated_at" = now() WHERE "code" = 'SIGNAL_PRODUCT_DISCONTINUED';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания выводит на рынок новый продукт, услугу, линейку, обновлённую версию или переиздание того, что она ПРОДАЁТ. Для сервисных компаний — новая услуга, тариф или формат обслуживания.', "boundary_ru" = 'Компания покупает что-то для своей работы (оборудование, транспорт, ИТ) → SIGNAL_OPERATIONS_INVESTMENT. Спецификация, паспорт продукта, сертификат, прайс или каталог, присланные с заказом или запросом, — нет сигнала. Новая позиция в НАШЕМ каталоге → INTERNAL_PRODUCT_STATUS_UPDATE. Новая позиция у поставщика, который предлагает её нам → SUPPLIER_PRICE_CHANGE или нет сигнала. Клиент обновляет ассортимент и рассматривает наши позиции → LISTING_OPPORTUNITY.', "cues_prompt_ru" = ARRAY['запускает новую линейку', 'представила новый продукт', 'вывела на рынок', 'новинка', 'новая услуга', 'новый формат', 'перезапуск', 'расширение ассортимента']::text[], "synonyms_ru" = '{"chat": ["у них новинка вышла", "запускают СТМ", "ассортимент полностью переделали", "новую линейку выкатили"], "news": ["компания представила новую линейку", "бренд выпустил лимитированную серию", "сеть запустила собственную торговую марку", "интегратор запустил новую услугу", "компания вывела на рынок новинку", "стартовали продажи новой модели", "расширила ассортимент"], "terms": ["«СТМ» (собственная торговая марка)", "линейка", "лимитка", "релонч", "новинка", "сезонная коллекция"], "business": ["в декабре запускаем новую сезонную коллекцию", "открываем направление сервиса для корпоративных клиентов", "выводим собственную марку стройматериалов", "перезапускаем бренд магазинов в новом формате"], "patterns": ["«[компания] запускает / представила [продукт]», «в продаже появится [продукт] с [даты]», «расширяет линейку [чем]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_OPERATIONS_INVESTMENT", "text": "«закупили новые станки»"}, {"code": null, "text": "«во вложении спецификация и сертификат»"}, {"code": "LISTING_OPPORTUNITY", "text": "«обновляем ассортимент, пришлите предложения»"}, {"code": "SIGNAL_REBRANDING", "text": "«сменили логотип и название»"}]'::jsonb, "example_ru" = '«Сеть «СтройМаркет» с 1 декабря запускает собственную марку лакокрасочных материалов в 40 магазинах.»', "updated_at" = now() WHERE "code" = 'SIGNAL_PRODUCT_NEWS';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["они переименовались", "новую вывеску повесили", "логотип поменяли", "сайт переделали"], "news": ["сеть провела ребрендинг", "бренд представил новый логотип", "компания сменила название на", "магазин откроется после ребрендинга под новой вывеской", "обновили айдентику", "перезапустили сайт на новой платформе"], "terms": ["ребрендинг", "рестайлинг", "айдентика", "фирменный стиль", "брендбук", "новый сайт", "редизайн"], "business": ["сообщаем, что с 01.12 компания работает под новым названием", "прошу обновить наименование в документах и в карточке клиента", "у нас обновился логотип, пришлём новые макеты для упаковки", "мы запустили новый сайт с онлайн-заказом"], "patterns": ["«[компания] теперь называется [название]», «[бренд] представил новый [логотип / стиль]», «работает под новым названием с [даты]»"]}'::jsonb, "example_ru" = '«С 1 декабря сеть «СтройМаркет» будет работать под новым названием «СтройДвор» и с новой концепцией.»', "counter_example_ru" = '«Просим учесть новые банковские реквизиты ООО «СтройМаркет» в счетах» → смена реквизитов, не ребрендинг.', "card_note_ru" = 'Назовите конкретное изменение (название, логотип, сайт); шаг — до запуска узнать у контакта клиента, что меняется в концепции и ассортименте, и обновить карточку клиента.', "updated_at" = now() WHERE "code" = 'SIGNAL_REBRANDING';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["у них выручка просела", "минус 10 % за год", "отчитались в убыток"], "news": ["выручка группы компаний за полугодие снизилась на 9 %", "чистый убыток по РСБУ вырос в 1,5 раза", "сопоставимые продажи упали на 4 %", "трафик в магазинах сократился на 11 % год к году"], "terms": ["выручка", "убыток", "МСФО", "РСБУ", "LFL", "г/г", "трафик"], "business": ["у нас выручка минус 15 % к прошлому году, поэтому закупки скромнее"], "patterns": ["«[показатель] снизился / упал на [N %] [к периоду]», «убыток составил [сумма]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "ACCOUNT_REVENUE_DECLINE_YOY", "text": "«клиент купил у нас меньше, чем в прошлом году»"}, {"code": "SIGNAL_INSOLVENCY", "text": "«введена процедура наблюдения»"}, {"code": "SIGNAL_DOWNSIZING", "text": "«закроем пять магазинов»"}, {"code": null, "text": "«сейчас тяжело»"}]'::jsonb, "example_ru" = '«Выручка группы компаний «Техносфера» за первое полугодие 2026 года снизилась на 9 % год к году.»', "counter_example_ru" = '«Группа компаний «Техносфера» закрывает два филиала» → это SIGNAL_DOWNSIZING.', "updated_at" = now() WHERE "code" = 'SIGNAL_RESULTS_NEGATIVE';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания публикует результаты с ростом: выручка, прибыль, продажи, трафик, число покупателей. Нужны число и период сравнения.', "synonyms_ru" = '{"chat": ["у них выручка прёт", "плюс 20 % за год", "отчитались хорошо"], "news": ["выручка сети за 9 месяцев выросла на 18 % год к году", "чистая прибыль по МСФО увеличилась вдвое", "сопоставимые продажи (LFL) выросли на 7 %", "логистическая компания отчиталась о росте выручки", "средний чек вырос на 12 %"], "terms": ["выручка", "EBITDA", "МСФО", "РСБУ", "LFL", "г/г", "кв/кв", "средний чек"], "business": ["по итогам года выручка у нас +20 %, расширяем ассортимент"], "patterns": ["«[показатель] вырос на [N %] [к периоду]», «по итогам [периода] [показатель] составил [сумма], [+N %]»"]}'::jsonb, "example_ru" = '«Выручка сети «СтройМаркет» за январь–сентябрь 2026 года выросла на 18 % год к году, до 2,4 млрд ₽.»', "counter_example_ru" = '«Сеть «СтройМаркет» рассчитывает на рост выручки в следующем году» → прогноз без факта.', "updated_at" = now() WHERE "code" = 'SIGNAL_RESULTS_POSITIVE';
--> statement-breakpoint
UPDATE "signal_category" SET "example_ru" = '«Рекламные расходы «СтройМаркета» в III квартале 2026: 6 млн ₽ против 11 млн ₽ годом ранее (−45 %).»', "updated_at" = now() WHERE "code" = 'SIGNAL_SPEND_DOWN';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Расходы клиента в категории, важной для нас, заметно растут — независимо от его бюджета у нас (агентство: рекламные расходы по данным мониторинга; поставщик: закупки категории, если есть внешний источник).', "updated_at" = now() WHERE "code" = 'SIGNAL_SPEND_UP';
--> statement-breakpoint
UPDATE "signal_category" SET "boundary_ru" = 'Просто участие как экспонент или спикер → SIGNAL_EVENT / SIGNAL_EVENT_UPCOMING. Совместный коммерческий проект с другой компанией → SIGNAL_PARTNERSHIP. Клиент просит НАС быть спонсором или дать продукцию на событие → PROMO_SUPPORT_REQUESTED.', "synonyms_ru" = '{"chat": ["они спонсируют фестиваль", "их стенд будет на марафоне как партнёр"], "news": ["сеть стала генеральным спонсором технологического фестиваля", "компания — официальный партнёр городского марафона", "бренд подписал спонсорский контракт с клубом", "логистическая компания выступила партнёром благотворительного забега"], "terms": ["спонсор", "генеральный партнёр", "титульный спонсор", "при поддержке", "благотворительность"], "business": ["в этом году мы спонсоры фестиваля, будет наш стенд на площадке"], "patterns": ["«[компания] стала [генеральным / официальным] [спонсором / партнёром] [события]», «при поддержке [компании]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_EVENT_UPCOMING", "text": "«будем стоять на выставке»"}, {"code": "SIGNAL_PARTNERSHIP", "text": "«запустили совместный продукт с производителем»"}, {"code": "PROMO_SUPPORT_REQUESTED", "text": "«поддержите наш фестиваль продукцией для участников»"}]'::jsonb, "example_ru" = '«Компания «Техносфера» стала официальным партнёром городского технологического фестиваля в Парке Горького.»', "counter_example_ru" = '«Компания «Техносфера» будет участником технологического фестиваля» → участие без спонсорства, SIGNAL_EVENT_UPCOMING.', "card_note_ru" = 'Не предполагайте коммуникацию вокруг спонсорства; шаг — спросить контакт клиента, будут ли под проект закупки или стенд на площадке, и только тогда предлагать.', "updated_at" = now() WHERE "code" = 'SIGNAL_SPONSORING';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Компания объявляет стратегическое решение с названным последствием для маркетинга, коммуникаций, рекламы или бюджета (для поставщика — для закупок и ассортимента): новая стратегия бренда, перепозиционирование, рост или сокращение маркетингового бюджета, пересмотр всех поставщиков. Конкретного действия ещё нет.', "synonyms_ru" = '{"chat": ["они уходят в премиум", "будут чистить поставщиков", "режут маркетинг", "новая стратегия, всё переигрывают"], "news": ["компания утвердила новую стратегию развития бренда", "сеть объявила о перепозиционировании в премиум", "маркетинговый бюджет вырастет на 30 %", "ретейлер пересмотрит ассортиментную матрицу", "сеть объявила о сокращении числа поставщиков", "компания делает ставку на собственные торговые марки"], "terms": ["стратегия", "перепозиционирование", "ассортиментная матрица", "пул поставщиков", "СТМ", "маркетинговый бюджет"], "business": ["в следующем году мы меняем ассортиментную политику", "будем пересматривать всех поставщиков в категории электротоваров", "руководство решило уйти в премиальный сегмент"], "patterns": ["«[компания] объявила / утвердила [стратегию]», «делает ставку на [что]», «пересматривает [бюджет / поставщиков / матрицу]»"]}'::jsonb, "example_ru" = '«Сеть «Гастроном Плюс» объявила новую стратегию: доля премиальных товаров в ассортименте вырастет до 40 %, поставщиков в каждой категории станет меньше.»', "updated_at" = now() WHERE "code" = 'SIGNAL_STRATEGY_ANNOUNCEMENT';
--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["гендир в подкасте рассказывал про планы", "думают, куда расти", "пока присматриваются"], "news": ["основатель ИТ-интегратора в интервью рассказал о планах", "генеральный директор сети ожидает замедления рынка", "компания рассматривает перенос производства", "ретейлер обсуждает новую организационную структуру", "прогноз компании на 2027 год"], "terms": ["интервью", "стратегия", "прогноз", "оргструктура", "планы развития"], "business": ["в следующем году думаем о новых форматах, пока ничего конкретного", "руководство обсуждает развитие, решения позже"], "patterns": ["«[руководитель] рассказал о [планах]», «[компания] рассматривает [вариант]», «ожидает [тенденцию] в [периоде]»"]}'::jsonb, "anti_cues_ru" = '[{"code": "SIGNAL_STRATEGY_ANNOUNCEMENT", "text": "«в следующем году сокращаем число поставщиков комплектующих»"}, {"code": "SIGNAL_CHANNEL_SHIFT", "text": "«переносим бюджет в digital»"}, {"code": "SALES_TENDER_INVITATION", "text": "«во вложении тендерная документация»"}]'::jsonb, "example_ru" = '«Основатель «Северного ветра» в интервью рассказал, что группа рассматривает выход в новые регионы, но решение примут не раньше весны.»', "counter_example_ru" = '«Основатель «Северного ветра»: в 2027 году мы сократим число поставщиков комплектующих с восьми до трёх» → названо последствие для закупок, SIGNAL_STRATEGY_ANNOUNCEMENT.', "updated_at" = now() WHERE "code" = 'SIGNAL_STRATEGY_CONTEXT';
--> statement-breakpoint
