UPDATE "signal_category" SET "example_ru" = '«С ноября сквозную аналитику «СтройМаркета» ведёт новое агентство, коллтрекинг переведён с Calltouch на CoMagic.»', "counter_example_ru" = '«На сайт «СтройМаркета» дополнительно поставили VK Пиксель» → инструмент добавлен, замены нет.', "updated_at" = now() WHERE "code" = 'SIGNAL_TRACKING_VENDOR_CHANGE';
