UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["они бренд зарегали", "знак подали, видимо, новый проект", "домен уже купили"], "news": ["компания подала в Роспатент заявку на товарный знак", "Роспатент зарегистрировал товарный знак", "предприниматель зарегистрировал бренд для нового проекта", "зарегистрирован домен под новый проект", "знак обслуживания по 37-му классу МКТУ"], "terms": ["Роспатент", "ФИПС", "МКТУ", "товарный знак", "ТЗ", "знак обслуживания", "домен .ru / .рф"], "business": ["мы зарегистрировали название нового сервиса, скоро анонс", "под новую марку уже купили домен"], "patterns": ["«[компания] подала заявку на [товарный знак]», «зарегистрирован [знак / домен] [название]»"]}'::jsonb, "example_ru" = '«ООО «Северный ветер» подало в Роспатент заявку на товарный знак «Вектор» по 7-му и 37-му классам МКТУ.»', "updated_at" = now() WHERE "code" = 'SIGNAL_TRADEMARK';
--> statement-breakpoint
UPDATE "signal_category" SET "definition_ru" = 'Клиент спрашивает, есть ли позиция на складе, сколько её осталось, когда будет поступление или новая партия.', "boundary_ru" = 'Заказ с количеством и просьбой отгрузить → ORDER_REQUESTED. Вопрос только о цене → SALES_PRICE_REQUEST. Бронь будущего поступления → PREORDER_REQUESTED (предложено). Просьба подобрать замену отсутствующей позиции → SUBSTITUTION_REQUESTED (предложено). Наш поставщик сообщает нам о задержке → SUPPLIER_DELIVERY_DELAY.', "cues_prompt_ru" = ARRAY['есть ли в наличии', 'остатки', 'когда будет поступление', 'сколько осталось', 'есть на складе?', 'когда приедет новая партия', 'появится ли', 'актуальные стоки']::text[], "synonyms_ru" = '{"chat": ["подшипники 6204 есть?", "а белая краска ещё осталась?", "скиньте стоки", "что по наличию?", "когда завоз?", "есть живьём?", "на складе сколько?", "а насосы когда будут?", "новая партия уже приехала?"], "terms": ["остатки", "сток", "сток-лист", "наличие", "поступление", "приход", "контейнер", "партия", "серия", "под заказ", "транзит"], "business": ["подскажите, пожалуйста, наличие", "просим прислать актуальные остатки", "уточните наличие следующих позиций", "когда ожидается поступление", "есть ли возможность поставить 30 кор. до конца месяца", "в каком объёме доступна позиция", "есть ли новая модель или только прошлогодняя", "пришлите сток-лист"], "patterns": ["«есть ли / есть / осталось ли» + позиция", "«когда будет / приедет / поступит» + позиция", "сколько + на складе / в наличии"]}'::jsonb, "anti_cues_ru" = '[{"code": "ORDER_REQUESTED", "text": "«отгрузите 5 кор. подшипников»"}, {"code": "SALES_PRICE_REQUEST", "text": "«сколько стоят подшипники»"}, {"code": "PREORDER_REQUESTED", "text": "«забронируйте нам 20 шт. из следующей партии»"}, {"code": "SUBSTITUTION_REQUESTED", "text": "«подшипников нет — что предложите вместо?»"}, {"code": "SUPPLIER_DELIVERY_DELAY", "text": "«контейнер задерживается на таможне» (поставщик нам)"}]'::jsonb, "example_ru" = '«Добрый день! Подскажите, есть ли в наличии подшипники 6204-2RS и когда ждать следующее поступление?»', "counter_example_ru" = '«Подшипники 6204 — 12 кор. на пятницу» → это заказ, а не вопрос о наличии.', "updated_at" = now() WHERE "code" = 'STOCK_AVAILABILITY_REQUEST';
--> statement-breakpoint
UPDATE "signal_category" SET "cues_prompt_ru" = ARRAY['чем заменить', 'подберите аналог', 'что есть похожее', 'если нет — предложите замену', 'замену в той же цене', 'близкое по характеристикам', 'вместо отсутствующего', 'аналог для каталога']::text[], "synonyms_ru" = '{"chat": ["а чем заменить?", "нет — давайте что-то похожее", "посоветуйте аналог", "что есть такого же по цене?", "подберите что-то вместо, чтобы каталог не переделывать"], "terms": ["аналог", "замена", "substitute", "в той же ценовой категории", "те же характеристики"], "business": ["просим предложить аналог отсутствующей позиции", "если этого кабеля нет, подберите замену в той же ценовой категории", "нужна замена позиции в ассортименте, производитель прекратил поставки", "предложите близкий по характеристикам аналог"], "patterns": ["нет / закончилось + чем заменить / подберите / предложите"]}'::jsonb, "anti_cues_ru" = '[{"code": "ORDER_CHANGE_REQUESTED", "text": "«замените в заказе модель А200 на А300»"}, {"code": "STOCK_AVAILABILITY_REQUEST", "text": "«кабель есть?»"}, {"code": "DELIVERY_DISCREPANCY", "text": "«привезли не ту позицию»"}]'::jsonb, "example_ru" = '«Раз датчиков серии DX нет до января, подберите аналог в той же цене — они у нас в базовом ассортименте.»', "counter_example_ru" = '«Вместо датчиков DX поставьте датчики серии MX» → клиент сам выбрал замену; это ORDER_CHANGE_REQUESTED.', "card_note_ru" = 'Пишите «Ответственный менеджер — предложить клиенту аналог отсутствующей позиции»; укажите позицию, цену и назначение (каталог, полка).', "note_ru" = 'Статус: proposed (new) · target block after approval: O
Closed by: `ORDER_CONFIRMED` (same topic)
