UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["контейнер встал в Новороссийске", "фура задерживается на границе", "завод не успевает, сдвиг на неделю", "этой позиции нет, остаток уйдёт в бэкордер", "приедет только половина", "таможня держит, ждём выпуска"], "terms": ["ETA", "ETD", "бэкордер", "backorder", "«ДТ» (декларация на товары)", "СВХ", "инвойс", "коносамент", "частичная отгрузка"], "business": ["сообщаем о переносе даты отгрузки", "ориентировочная дата прибытия сдвигается на", "груз задержан на таможенном посту", "товар будет поставлен частично", "позиция временно недоступна к заказу", "производитель не подтверждает объём", "задержка производства партии", "судно прибывает позже плана", "сертификаты не получены, отгрузка откладывается"], "patterns": ["«задерживается / переносится / сдвигается» + поставка / отгрузка / контейнер", "«нет в наличии» + у производителя / на складе поставщика", "«новая дата» + прибытия / отгрузки"]}'::jsonb, "note_ru" = 'Relations: — (boundary vs `COMPLAINT_TIMING`, `DELIVERY_SCHEDULE_REQUEST`)
