--> statement-breakpoint
UPDATE "signal_category" SET "synonyms_ru" = '{"chat": ["кинул новый прайс", "с декабря плюс 7 %", "евро вырос, поднимаем", "скинули цены на остатки 2021", "вот дилерские на новую линейку"], "terms": ["прайс", "ПЛ", "EXW", "FCA", "DAP", "дилерская цена", "закупочная цена", "таможенная пошлина", "курсовая разница"], "business": ["направляем актуальный прайс-лист", "уведомляем об изменении цен с", "в связи с ростом стоимости сырья цены увеличиваются на", "индексация отпускных цен", "новые условия для дистрибьюторов", "корректировка цен в связи с курсом евро", "цены указаны с учётом НДС", "прайс на новую партию"], "patterns": ["«цены действуют / вступают в силу» + дата", "«повышение / снижение / индексация» + цен + процент", "«прайс-лист» + во вложении"]}'::jsonb, "example_ru" = '«Уведомляем, что с 01.12.2026 закупочные цены на всю линейку кабельной продукции увеличиваются на 6 % в связи с ростом цен на медь. Новый прайс во вложении.»', "counter_example_ru" = '«Добрый день! Пришлите, пожалуйста, ваш актуальный прайс на кабель» от клиента → SALES_PRICE_REQUEST.', "updated_at" = now() WHERE "code" = 'SUPPLIER_PRICE_CHANGE';
