-- 4. Risk types, stage-rule templates, relations, pack ──────────────────────
-- Deal-type ids in code notes not covered by the rewrite.
UPDATE "signal_category" SET "note_ru" = replace(replace(replace("note_ru", '`wine_card_listing`', '`listing`'), '`chain_listing`', '`listing`'), '`new_venue`', '`new_location`')
WHERE "note_ru" ~ '(wine_card_listing|chain_listing|new_venue)';
--> statement-breakpoint
UPDATE "deal_risk_type" SET "description_ru" = 'Клиент сообщил, что убирает наши позиции из своего ассортимента или матрицы. Объём поставок по сделке может упасть или исчезнуть.',
  "note_ru" = replace(replace("note_ru", 'is `wine_card_listing`, `chain_listing`, `supply_agreement` or `renewal`', 'is `listing`, `supply_agreement` or `renewal`'), 'a `tender` or `new_venue` deal of another venue', 'a `tender` or `new_location` deal of another location')
WHERE "code" = 'DELISTING';
--> statement-breakpoint
UPDATE "deal_risk_type" SET "note_ru" = replace("note_ru", ' (base «условия справедливые»; must be switched on for IN4COM, Open point 14)', ' (base «условия справедливые»)')
WHERE "code" = 'COMPETITOR_PRICE';
--> statement-breakpoint
UPDATE "deal_risk_type" SET "label_ru" = 'Смена закупщика / ЛПР',
  "description_ru" = replace("description_ru", '(закупщик, сомелье, шеф, категорийный менеджер)', '(закупщик, руководитель, категорийный менеджер)')
WHERE "code" = 'DECISION_MAKER_CHANGE';
--> statement-breakpoint
UPDATE "deal_risk_type" SET "description_ru" = replace("description_ru", 'по вводу, выбору поставщика', 'по вводу позиций, выбору поставщика')
WHERE "code" = 'DECISION_DELAYED' AND "description_ru" NOT LIKE '%по вводу позиций%';
--> statement-breakpoint
UPDATE "deal_risk_type" SET "note_ru" = replace(replace("note_ru", '`distribution.maxDeferralDays`', '`deals.maxDeferralDays`'), '`distribution.maxCreditLimitRub`', '`deals.maxCreditLimitRub`')
WHERE "code" = 'PAYMENT_TERMS_ABOVE_POLICY';
--> statement-breakpoint
UPDATE "deal_risk_type" SET "description_ru" = replace("description_ru", '(качество вина, сроки, расхождения при приёмке)', '(качество товара, сроки, расхождения при приёмке)')
WHERE "code" = 'REPEATED_COMPLAINTS';
--> statement-breakpoint
UPDATE "deal_risk_type" SET "description_ru" = replace("description_ru", '(ввод в карту, тендер)', '(ввод в ассортимент, тендер)')
WHERE "code" = 'NO_STOCK_FOR_DEAL';
--> statement-breakpoint
-- Generic deal types: wine_card_listing + chain_listing → listing, new_venue → new_location.
DELETE FROM "signal_stage_rule" WHERE "id" = 'tpl:distribution:2';
--> statement-breakpoint
UPDATE "signal_stage_rule" SET "deal_types" = ARRAY(
  SELECT DISTINCT ON (t) t FROM (
    SELECT CASE x WHEN 'wine_card_listing' THEN 'listing' WHEN 'chain_listing' THEN 'listing' WHEN 'new_venue' THEN 'new_location' ELSE x END AS t, o
    FROM unnest("deal_types") WITH ORDINALITY AS u(x, o)
  ) s ORDER BY t, o)
WHERE "deal_types" && ARRAY['wine_card_listing','chain_listing','new_venue']::text[];
--> statement-breakpoint
UPDATE "signal_stage_rule" SET "note_ru" = replace(replace("note_ru", '`new_venue`', '`new_location`'), 'active only after DS7 approval', 'active only after the block U codes are approved')
WHERE "note_ru" LIKE '%new_venue%' OR "note_ru" LIKE '%DS7%';
--> statement-breakpoint
UPDATE "signal_stage_rule" SET "id" = replace("id", 'tpl:distribution:', 'tpl:base:')
WHERE "id" LIKE 'tpl:distribution:%';
--> statement-breakpoint
UPDATE "signal_relation" SET "note_ru" = 'outranks base COMPLAINT_QUANTITY on the same subject (a shortage found at acceptance is this code)'
WHERE "id" = 'rel:outranks:DELIVERY_DISCREPANCY:COMPLAINT_QUANTITY';
--> statement-breakpoint
UPDATE "signal_relation" SET "note_ru" = 'both with base COMPLAINT_QUALITY (return of faulty goods = complaint + task)'
WHERE "id" = 'rel:both:COMPLAINT_QUALITY:RETURN_REQUESTED';
--> statement-breakpoint
UPDATE "signal_pack" SET "description_ru" = 'Все коды сигналов: продажи, договоры, счета, обратная связь, встречи, контакты, рынок, команда, аккаунт, конкуренты, поставщики, заказы, наличие и образцы, ассортимент клиента, доставка и возвраты, документы, оплата. Включение отдельных кодов — по организации.'
WHERE "code" = 'base';
--> statement-breakpoint

-- 5. Registry version (max + 1) and change log — written once ───────────────
DO $$
DECLARE v integer;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "signal_registry_change" WHERE "id" = 'r22:summary') THEN
    SELECT coalesce(max("version"), 0) + 1 INTO v FROM "signal_taxonomy_version";
    INSERT INTO "signal_taxonomy_version" ("version", "summary") VALUES
